INSERT INTO `contents` (`title_ru`, `alias`, `html_ru`, `title_en`, `html_en`) VALUES ('Законы игры', 'rules', '<div class="content-article"><section class="content-article-section"><h2>Правила игры</h2><div class="content-article-section-body"><p>Эти правила обязательны для всех игроков XNova. Их цель — честная конкуренция и уважительное общение. За соблюдением правил следит администрация проекта.</p><p>Часть ограничений проверяется игрой автоматически, остальные — администрацией по игровым журналам и обращениям. Возможность выполнить действие в интерфейсе не означает, что оно разрешено правилами.</p><p>Для вопросов, жалоб и согласования спорных действий используйте раздел <a href="/support">«Поддержка»</a>. Если вход в аккаунт недоступен, обратитесь к администрации через страницу <a href="/contacts">«Контакты»</a>. В этих правилах РО означает режим отпуска.</p></div></section><section class="content-article-section"><h2>1. Аккаунты и доступ</h2><div class="content-article-section-body"><h3>1.1. Один игрок — один аккаунт</h3><p>В одной вселенной игроку разрешён только один аккаунт. Запрещены создание дополнительных аккаунтов, управление ими и совместная игра нескольких людей на одном аккаунте, кроме временного ухода по пункту 1.2. Создание нового аккаунта для обхода блокировки также запрещено.</p><p>Владелец обязан сохранять доступ к электронной почте, указанной в настройках, и защищать данные для входа. При восстановлении доступа администрация может запросить подтверждение владения этой почтой. Не передавайте пароли в обращениях, чатах и игровых сообщениях.</p><h3>1.2. Временный уход за аккаунтом — ситтинг</h3><p>Разрешён уход за одним чужим аккаунтом помимо собственного продолжительностью не более 24 часов от первого до последнего действия. После завершения ухода владелец не может снова передавать аккаунт на уход в течение 7 дней, а присматривающий игрок — брать на уход этот или другой аккаунт в течение 7 дней.</p><ul><li>Разрешены запуск и отмена строительства и исследований, а также перевозка ресурсов между собственными планетами аккаунта.</li><li>Запрещены атаки, участие в совместных атаках, уничтожение лун, шпионаж, использование сенсорной фаланги и межпланетных ракет, отправка ресурсов другим игрокам.</li><li>Миссия «Переработать» разрешена только для сохранения флота на время отсутствия владельца, а не для сбора чужих обломков.</li></ul><p>Условия ситтинга контролирует администрация: отдельного режима с автоматическим ограничением полномочий в игре нет. Для длительного отсутствия используйте режим отпуска.</p><h3>1.3. Обмен и продажа</h3><p>Обмен аккаунтами необходимо заранее согласовать с администрацией: каждый владелец должен подтвердить согласие через поддержку. Самостоятельная передача данных для входа не гарантирует последующее восстановление доступа. Продажа аккаунтов и попытки их продажи запрещены.</p></div></section><section class="content-article-section"><h2>2. Игра с одного компьютера или IP-адреса</h2><div class="content-article-section-body"><p>Разным людям разрешено играть с одного устройства или через общее интернет-соединение. Сообщите об этом в поддержку, указав имена всех соответствующих аккаунтов. Общий IP-адрес не разрешает одному человеку управлять несколькими аккаунтами.</p><p>При постоянной игре с одного устройства или IP-адреса запрещены передачи ресурсов и отправка флотов между такими аккаунтами, договорные бои и совместные действия для получения преимущества. Исключение для временного ухода действует только в пределах пункта 1.2.</p><p>Это правила поведения, а не обещание автоматической блокировки отправки флота по IP-адресу. Нарушения рассматриваются администрацией как возможное управление несколькими аккаунтами.</p></div></section><section class="content-article-section"><h2>3. Прокачка и помощь другим игрокам</h2><div class="content-article-section-body"><p><strong>Прокачка запрещена.</strong> Под ней понимается передача выгоды от более слабого по общим очкам игрока более сильному без равноценного обмена или предусмотренного ниже основания. Членство в одном альянсе не даёт исключения. Запрет распространяется на транспорт ресурсов, подставные атаки, намеренную потерю флота и передачу обломков, в том числе через посредников.</p><p>Обычная добыча в честном бою не считается прокачкой. При споре учитываются общие очки участников на момент передачи, договорённости и фактическое движение ресурсов.</p><p>Если ресурсы от более слабого игрока пришли по ошибке, не расходуйте их: сообщите в поддержку и верните отправителю. Если возврату мешают ограничения транспорта, укажите это в обращении и согласуйте порядок возврата.</p><h3>3.1. Попытки создания луны</h3><p>Договорные атаки для создания луны разрешены. Более сильный по рейтингу участник не должен получать прибыль. Компенсация дейтерия, потраченного на полёт, запрещена. Расчёты ресурсами необходимо завершить в течение 3 суток после попытки. Сохраняйте боевые отчёты и сведения о сборе обломков. Договорённость не гарантирует появления луны и не отменяет ограничений на атаки.</p><h3>3.2. Восстановление флота</h3><p>После потери флота разрешена помощь от игроков любого уровня на сумму не более 50% стоимости потерянного флота. Обратиться в поддержку необходимо не позднее 5 дней после боя; срок получения помощи — 7 дней с момента обращения. Приложите боевой отчёт и учитывайте суммарную помощь от всех участников. По достижении предела дальнейшая помощь от более слабых игроков запрещена.</p><h3>3.3. Сбор обломков союзниками</h3><p>Члены альянса могут помочь собрать обломки после атаки и передать их участнику боя. До передачи ресурсов и не позднее 3 суток после атаки сообщите в поддержку данные боя, имена сборщиков и собранные объёмы. Сборщик может оставить ресурсы для возмещения фактических затрат на полёт переработчиков и транспортников по курсу из пункта 4.</p><h3>3.4. Другие договорённости</h3><p>Запрещены займы под проценты и вымогательство ресурсов за ненападение. О таких требованиях сообщайте в поддержку. Обломки прощального договорного боя должны остаться у его участников соразмерно их потерям; уход из игры не разрешает передать всё имущество более сильному игроку.</p><p>Спорные схемы помощи и расчётов согласуйте с администрацией до передачи ресурсов. Все исключения сохраняют силу только при соблюдении остальных правил и технических ограничений игры.</p></div></section><section class="content-article-section"><h2>4. Торговля и транспорт ресурсов</h2><div class="content-article-section-body"><p>Курс обмена между игроками: <strong>металл : кристалл : дейтерий = 4 : 2 : 1</strong>. Одна единица дейтерия равна двум единицам кристалла или четырём единицам металла; одна единица кристалла — двум единицам металла. Встречную передачу при торговле и возврат займа необходимо завершить в течение 3 суток после получения ресурсов. Нарушения условий обмена рассматриваются по правилу о прокачке.</p><p>Для миссии «Транспорт» другому игроку действуют автоматические ограничения:</p><ul><li>Не более одной отправки от одного игрока одному получателю за последние 24 часа.</li><li>Не более трёх таких отправок за последние 7 дней.</li><li>Нельзя отправлять транспорт игроку, который не заходил в игру более 7 дней.</li></ul><p>Лимиты общие для всех планет отправителя и получателя. Они учитывают отправку, а не доставку; отзыв транспорта не освобождает лимит. Перевозки между собственными планетами под эти ограничения не подпадают. Планируйте сделки и возвраты заранее; если выполнить обязательство мешает ограничение игры, обратитесь в поддержку до истечения срока.</p><p>Встроенный <a href="/merchant">торговец</a> обменивает ресурсы на текущей планете по тому же курсу и списывает 1 кредит за операцию. Это отдельная игровая услуга, для неё не требуется транспорт другому игроку.</p><p>Продажа и покупка ресурсов, флотов, аккаунтов и иных игровых преимуществ между игроками за реальные деньги запрещены. Использование предусмотренных проектом платных услуг не относится к таким сделкам.</p></div></section><section class="content-article-section"><h2>5. Атаки, башинг и войны</h2><div class="content-article-section-body"><h3>5.1. Автоматический лимит атак</h3><p>Один игрок может отправить не более <strong>трёх флотов с заданием «Атаковать» на одни координаты за календарный день сервера</strong>. Счётчик начинается заново в полночь по серверному времени; это не скользящий период в 24 часа.</p><ul><li>Планета, луна и военная база на одних координатах используют общий лимит.</li><li>Атаки со всех планет одного аккаунта учитываются вместе.</li><li>Учитывается отправка флота, независимо от результата боя. Отозванная атака также остаётся в счётчике.</li><li>Неактивность защитника не отменяет этот лимит.</li><li>Межпланетные ракеты, шпионаж, присоединение к совместной атаке и миссия уничтожения луны не входят в автоматический счётчик обычных атак.</li></ul><p>Намеренный обход баш-контроля запрещён, в том числе с использованием совместных атак или ошибок игры. Отсутствие автоматического запрета не освобождает от ответственности; жалобы на обход рассматривает администрация.</p><h3>5.2. Война альянсов</h3><p>Исключение из лимита действует между участниками альянсов с подтверждённым состоянием войны. Заявка оформляется в разделе <a href="/alliance/diplomacy">«Дипломатия»</a> и должна быть принята другим альянсом. Одностороннее объявление в чате или сообщении не отменяет лимит. После прекращения войны снова действует обычный лимит; уже учтённые за день отправки сохраняются.</p><p>Война не отменяет защиту новичков, режим отпуска, запрет прокачки и правила общения.</p></div></section><section class="content-article-section"><h2>6. Защита игроков и режим отпуска</h2><div class="content-article-section-body"><p>Игра ограничивает ряд миссий с учётом общих очков игроков и настроек защиты новичков. Доступность задания проверяется при отправке флота. Длительная неактивность и блокировка могут отключать защиту по очкам; это не отменяет баш-контроль.</p><p>Режим отпуска включается в <a href="/options">настройках</a>. Для включения не должно быть собственных флотов в полёте и незавершённых очередей строительства, производства или исследований. Минимальная продолжительность задаётся настройками вселенной; дата доступного выхода отображается в интерфейсе. После этого срока отпуск нужно отключить самостоятельно.</p><p>Отпуск запрещает новые отправки флотов к игроку, кроме сбора обломков, и новые ракетные атаки. Уже отправленные к игроку флоты автоматически не отзываются: включение отпуска не гарантирует защиту от ранее начавшейся атаки.</p><p>Во время отпуска производство ресурсов приостановлено, а основные игровые действия ограничены. После выхода проверьте настройки выработки на планетах.</p></div></section><section class="content-article-section"><h2>7. Ошибки игры и автоматизация</h2><div class="content-article-section-body"><p>Запрещено использовать ошибки игры для получения ресурсов, кораблей, очков, доступа к чужим данным или другого преимущества. Нельзя повторять ошибочную операцию ради выгоды, скрывать её использование или помогать другим её использовать.</p><p>Об обнаруженной ошибке сообщите в поддержку: опишите действия, ожидаемый и фактический результат, время и координаты. Не публикуйте способы эксплуатации до устранения проблемы. До ответа администрации не расходуйте ошибочно полученное имущество.</p><p>Запрещены сторонние боты, макросы, автоматические и полуавтоматические скрипты, которые выполняют игровые действия за пользователя, обходят ограничения или создают чрезмерную нагрузку. Обычные средства браузера и расчёты по вручную введённым данным допустимы, если они не управляют аккаунтом и не нарушают работу игры.</p><p>Управляемые сервером игровые ИИ не являются пользовательскими ботами. Их наличие не разрешает автоматизацию аккаунтов игроков.</p></div></section><section class="content-article-section"><h2>8. Общение и пользовательские материалы</h2><div class="content-article-section-body"><p>Правила общения распространяются на общий и личный чат, игровые сообщения, чат альянса, обращения в поддержку, имена игроков, названия планет и альянсов, описания, изображения и ссылки.</p><ul><li>Запрещены угрозы в реальной жизни, вымогательство, травля, грубые оскорбления игроков и их близких, а также нецензурная брань.</li><li>Запрещены публикация чужих персональных данных без согласия, выдача себя за администрацию и обман с целью получить доступ к аккаунту.</li><li>Запрещены спам, навязчивая реклама, массовая рассылка и флуд. Обычное приглашение в альянс допустимо, но повторные нежелательные приглашения могут считаться спамом.</li><li>Запрещены порнография, дискриминационные материалы, пропаганда насилия, экстремизма и терроризма, а также соответствующие названия и символика.</li></ul><p>Игра поддерживает русский и английский языки. Сам по себе выбор языка не является нарушением. В личной переписке и внутри альянса участники могут договориться об удобном языке; правила уважительного общения действуют на любом языке.</p><p>Не переносите в игру политические конфликты и межнациональные споры. Если содержание или название вызывает сомнения, уточните его допустимость у администрации. При жалобе сохраняйте сообщения и указывайте их автора и время отправки.</p></div></section><section class="content-article-section"><h2>9. Поддержка и обжалование</h2><div class="content-article-section-body"><p>Обращайтесь в <a href="/support">поддержку</a> по вопросам нарушений, потерь, ошибок и спорных договорённостей. Укажите понятную тему, имя и ID аккаунта, время события, координаты, участников и номера или ссылки на боевые отчёты. Продолжайте переписку в одном обращении, чтобы сохранить контекст.</p><p>Сведения о блокировках, их причинах, сроках и принявшем решение сотруднике доступны на странице <a href="/blocked">«Заблокированные»</a>. Если вы не согласны с решением, изложите факты и основания для пересмотра в обращении. При недоступном входе используйте <a href="/contacts">контакты администрации</a>.</p><p>Запрещены подделка доказательств, намеренный обман и попытки получить другое решение путём сокрытия предыдущего обращения. Пересмотр выполняет администрация с учётом материалов дела.</p><p>Потери из-за ошибок, сбоев связи или действий самого игрока не восстанавливаются автоматически. Возможность восстановления рассматривается индивидуально по доступным игровым журналам.</p></div></section><section class="content-article-section"><h2>10. Ответственность за нарушения</h2><div class="content-article-section-body"><p>Администрация учитывает характер нарушения, полученную выгоду, последствия и повторность. В зависимости от случая применяются предупреждение, требование прекратить нарушение или вернуть ресурсы, блокировка с РО либо без него. Блокировка без РО сама по себе не защищает планеты и флот от атак.</p><ul><li><strong>Прокачка:</strong> первое нарушение — блокировка на 3 дня с РО, повторное — на 7 дней с РО; дальнейшие нарушения могут привести к прекращению доступа к игре.</li><li><strong>Обход баш-контроля:</strong> первое нарушение — 1 день с РО, повторное — до 3 дней с РО.</li><li><strong>Оскорбления:</strong> от 1 дня без РО; при повторениях срок увеличивается до 3, 7 и 14 дней, вплоть до прекращения доступа.</li><li><strong>Спам и флуд:</strong> первое нарушение — 1 день без РО, повторное — 3 дня без РО; дальнейшие нарушения могут привести к прекращению доступа.</li><li><strong>Несколько аккаунтов, нарушение условий ситтинга, продажа аккаунта, эксплуатация ошибок, запрещённая автоматизация, реальные угрозы и запрещённые материалы:</strong> блокировка вплоть до прекращения доступа к игре.</li></ul><p>Причина и срок конкретной блокировки фиксируются администрацией. Блокировка и удаление аккаунта — разные действия: автоматическое удаление через фиксированный срок не является частью перечисленных санкций. Ответственность определяется по участию в нарушении; само членство в альянсе нарушителя не доказывает вину.</p></div></section><section class="content-article-section"><h2>11. Кредиты и платные возможности</h2><div class="content-article-section-body"><p>Кредиты и другие предусмотренные игрой платные возможности используются на условиях, указанных в соответствующих разделах интерфейса. Они не дают права нарушать правила и не освобождают от блокировки. Перед использованием услуги ознакомьтесь с её стоимостью, действием и сроком, если он предусмотрен.</p></div></section><section class="content-article-section"><h2>12. Действие и изменение правил</h2><div class="content-article-section-body"><p>Участие в игре означает принятие этих правил и <a href="/content/agreement">пользовательского соглашения</a>. Незнание правил не освобождает от их соблюдения.</p><p>Актуальная редакция публикуется на этой странице. Об изменениях и дате их вступления в силу администрация сообщает в игровых объявлениях не менее чем за 2 недели. Для срочных мер по защите игры и небольших уточнений срок может быть сокращён; это указывается в объявлении. Если формулировка допускает несколько толкований, уточните её в поддержке до совершения спорного действия.</p></div></section></div>', 'Game rules', '<div class="content-article"><section class="content-article-section"><h2>Game rules</h2><div class="content-article-section-body"><p>These rules apply to every XNova player. They support fair competition and respectful communication. The project administration oversees compliance.</p><p>Some restrictions are enforced automatically; others are reviewed by the administration using game logs and player reports. Being able to perform an action in the interface does not mean it is permitted by these rules.</p><p>Use <a href="/support">Support</a> for questions, complaints and clarification of disputed actions. If you cannot access your account, use the <a href="/contacts">Contacts</a> page to reach the administration. Vacation mode is abbreviated as VM below.</p></div></section><section class="content-article-section"><h2>1. Accounts and access</h2><div class="content-article-section-body"><h3>1.1. One player, one account</h3><p>Each player may have only one account in a universe. Creating or controlling additional accounts and sharing an account are prohibited, except for temporary sitting under section 1.2. Creating another account to evade a suspension is also prohibited.</p><p>Owners must retain access to the email address in their settings and protect their login credentials. The administration may request proof of email ownership when restoring access. Never include passwords in support requests, chats or game messages.</p><h3>1.2. Temporary account sitting</h3><p>You may look after one other account in addition to your own for no more than 24 hours from the first to the last action. After sitting ends, the owner must wait 7 days before arranging another sitting period, and the sitter must wait 7 days before looking after that or any other account.</p><ul><li>Starting and cancelling construction and research, and moving resources between planets belonging to the account, are allowed.</li><li>Attacks, participation in joint attacks, moon destruction, espionage, sensor phalanx scans, interplanetary missiles and sending resources to other players are prohibited.</li><li>Recycling missions may only be used to keep the fleet in flight while the owner is away, not to collect other players’ debris.</li></ul><p>The administration enforces sitting conditions. There is no separate game mode that automatically restricts a sitter’s permissions. Use vacation mode for longer absences.</p><h3>1.3. Account exchanges and sales</h3><p>Account exchanges require prior agreement with the administration: each owner must confirm consent through Support. Handing over login credentials independently does not guarantee that access can later be restored. Selling accounts or attempting to sell them is prohibited.</p></div></section><section class="content-article-section"><h2>2. Shared devices and IP addresses</h2><div class="content-article-section-body"><p>Different people may play on the same device or internet connection. Notify Support and identify all accounts involved. A shared IP address does not permit one person to control multiple accounts.</p><p>Accounts regularly using the same device or IP address must not transfer resources or send fleets to one another, arrange staged battles or coordinate actions to gain an advantage. The temporary sitting exception applies only within section 1.2.</p><p>These are conduct rules, not a promise that fleet dispatch will automatically be blocked based on IP address. The administration reviews violations as possible multi-accounting.</p></div></section><section class="content-article-section"><h2>3. Pushing and player assistance</h2><div class="content-article-section-body"><p><strong>Pushing is prohibited.</strong> It means transferring value from a player with fewer total points to a stronger player without an equivalent exchange or an exception listed below. Membership in the same alliance does not provide an exemption. This applies to resource transports, staged attacks, deliberate fleet losses and transfers of debris, including through intermediaries.</p><p>Loot from a genuine battle is not pushing. Reviews take into account the participants’ total points at the time of transfer, their agreements and the actual movement of resources.</p><p>If a weaker player sends resources by mistake, do not spend them. Contact Support and return them to the sender. If transport restrictions prevent a return, explain this in your request and agree on how to proceed.</p><h3>3.1. Moon creation attempts</h3><p>Agreed attacks intended to create a moon are allowed. The higher-ranked participant must not make a profit. Reimbursement of deuterium spent on the flight is prohibited. Resource settlements must be completed within 3 days of the attempt. Keep battle reports and debris collection records. An agreement does not guarantee a moon and does not waive attack restrictions.</p><h3>3.2. Fleet recovery</h3><p>After losing a fleet, a player may receive assistance from players of any level up to 50% of the lost fleet’s value. Contact Support within 5 days of the battle; assistance may be received for 7 days from that request. Include the battle report and count contributions from all participants together. Once the limit is reached, further assistance from weaker players is prohibited.</p><h3>3.3. Debris collection by allies</h3><p>Alliance members may help collect debris after an attack and transfer it to a battle participant. Before transferring the resources, and within 3 days of the attack, provide Support with battle details, collector names and amounts collected. Collectors may retain resources to cover actual fuel costs for recyclers and transports at the exchange rate in section 4.</p><h3>3.4. Other arrangements</h3><p>Interest-bearing loans and demanding resources in exchange for non-aggression are prohibited. Report such demands to Support. Debris from a staged farewell battle must remain with its participants in proportion to their losses. Leaving the game does not permit transferring all assets to a stronger player.</p><p>Clarify disputed assistance or settlement arrangements with the administration before transferring resources. All exceptions remain subject to the other rules and the game’s technical restrictions.</p></div></section><section class="content-article-section"><h2>4. Trading and resource transport</h2><div class="content-article-section-body"><p>The exchange rate between players is <strong>metal : crystal : deuterium = 4 : 2 : 1</strong>. One unit of deuterium equals two units of crystal or four units of metal; one unit of crystal equals two units of metal. Complete the return leg of a trade or repay a loan within 3 days of receiving resources. Breaches of exchange conditions are reviewed under the pushing rule.</p><p>Transport missions to another player have these automatic limits:</p><ul><li>No more than one dispatch from a sender to the same recipient within the previous 24 hours.</li><li>No more than three such dispatches within the previous 7 days.</li><li>No transport to a player who has not logged in for more than 7 days.</li></ul><p>These limits combine all planets of the sender and recipient. Dispatch, rather than delivery, counts; recalling a transport does not restore the allowance. Transfers between your own planets are exempt from these limits. Plan trades and repayments in advance. If a game restriction prevents you from fulfilling an obligation, contact Support before the deadline.</p><p>The built-in <a href="/merchant">Merchant</a> exchanges resources on the current planet at the same rate and charges 1 credit per transaction. This is a separate game service and does not require a transport to another player.</p><p>Buying or selling resources, fleets, accounts or other game advantages between players for real money is prohibited. Paid services provided by the project are separate from such transactions.</p></div></section><section class="content-article-section"><h2>5. Attacks, bashing and wars</h2><div class="content-article-section-body"><h3>5.1. Automatic attack limit</h3><p>A player may dispatch no more than <strong>three fleets on an Attack mission to the same coordinates per server calendar day</strong>. The counter resets at midnight server time; it is not a rolling 24-hour window.</p><ul><li>A planet, moon and military base at the same coordinates share one limit.</li><li>Attacks from all planets of an account count together.</li><li>Fleet dispatch counts regardless of the battle outcome. Recalled attacks remain in the counter.</li><li>Defender inactivity does not waive this limit.</li><li>Interplanetary missiles, espionage, joining a joint attack and moon destruction missions are not included in the automatic counter for ordinary attacks.</li></ul><p>Deliberately bypassing the bashing limit is prohibited, including through joint attacks or game errors. The absence of an automatic block does not remove responsibility; the administration reviews reports of circumvention.</p><h3>5.2. Alliance wars</h3><p>The limit exception applies between members of alliances with a confirmed war status. Submit the request through <a href="/alliance/diplomacy">Diplomacy</a>; the other alliance must accept it. A unilateral announcement in chat or a message does not waive the limit. Once the war ends, the normal limit applies again; dispatches already counted that day remain recorded.</p><p>War does not waive newbie protection, vacation mode, the prohibition on pushing or communication rules.</p></div></section><section class="content-article-section"><h2>6. Player protection and vacation mode</h2><div class="content-article-section-body"><p>The game restricts certain missions based on players’ total points and newbie protection settings. Mission availability is checked at dispatch. Extended inactivity and suspension may disable points-based protection; they do not waive the bashing limit.</p><p>Enable vacation mode in <a href="/options">Settings</a>. You must have no fleets of your own in flight and no unfinished construction, production or research queues. The universe settings determine the minimum duration; the interface shows when you may leave vacation mode. You must disable it manually after that time.</p><p>Vacation mode prevents new fleets from being sent to the player, except for debris collection, and prevents new missile attacks. Fleets already sent to the player are not automatically recalled: enabling vacation mode does not guarantee protection from an attack already in progress.</p><p>Resource production is paused and major game actions are restricted during vacation. Check production settings on your planets after leaving vacation mode.</p></div></section><section class="content-article-section"><h2>7. Game errors and automation</h2><div class="content-article-section-body"><p>Exploiting game errors to obtain resources, ships, points, access to other players’ data or any other advantage is prohibited. Do not repeat a faulty operation for profit, conceal exploitation or help others exploit an error.</p><p>Report errors through Support with the steps taken, expected and actual results, time and coordinates. Do not publish exploitation instructions before the issue is fixed. Do not spend assets obtained through an error while awaiting the administration’s response.</p><p>Third-party bots, macros, automated and semi-automated scripts that perform game actions for a user, bypass restrictions or create excessive load are prohibited. Ordinary browser tools and calculations using manually entered data are allowed if they do not control the account or disrupt the game.</p><p>Server-controlled AI players are not user-operated bots. Their presence does not permit players to automate their accounts.</p></div></section><section class="content-article-section"><h2>8. Communication and user content</h2><div class="content-article-section-body"><p>Communication rules apply to public and private chat, game messages, alliance chat, support requests, player names, planet and alliance names, descriptions, images and links.</p><ul><li>Real-life threats, extortion, harassment, abusive insults directed at players or their relatives, and profanity are prohibited.</li><li>Publishing another person’s personal information without consent, impersonating the administration and deception intended to gain account access are prohibited.</li><li>Spam, intrusive advertising, mass messaging and flooding are prohibited. An ordinary alliance invitation is allowed, but repeated unwanted invitations may be treated as spam.</li><li>Pornography, discriminatory material, promotion of violence, extremism or terrorism, and related names and symbols are prohibited.</li></ul><p>The game supports Russian and English. Language choice alone is not a violation. Participants in private correspondence and alliances may agree on a convenient language; respectful communication rules apply in every language.</p><p>Keep political conflicts and disputes between nationalities out of the game. If you are unsure about content or a name, ask the administration. When reporting abuse, keep the messages and identify their author and time.</p></div></section><section class="content-article-section"><h2>9. Support and appeals</h2><div class="content-article-section-body"><p>Contact <a href="/support">Support</a> about violations, losses, errors and disputed arrangements. Provide a clear subject, account name and ID, event time, coordinates, participants and battle report IDs or links. Continue in the same request to preserve context.</p><p>Suspensions, reasons, durations and the responsible staff member are listed on the <a href="/blocked">Blocked players</a> page. To appeal a decision, explain the facts and grounds for review. If you cannot log in, use the <a href="/contacts">administration contacts</a>.</p><p>Fabricating evidence, deliberate deception and concealing earlier requests to obtain a different decision are prohibited. The administration reviews decisions based on the available evidence.</p><p>Losses caused by errors, connection failures or a player’s own actions are not restored automatically. Restoration is considered individually based on available game logs.</p></div></section><section class="content-article-section"><h2>10. Consequences of violations</h2><div class="content-article-section-body"><p>The administration considers the nature of a violation, benefits gained, consequences and repeated conduct. Depending on the case, measures include a warning, a requirement to stop the violation or return resources, or suspension with or without VM. Suspension without VM does not itself protect planets or fleets from attacks.</p><ul><li><strong>Pushing:</strong> 3 days with VM for a first violation and 7 days with VM for a repeat; further violations may result in termination of game access.</li><li><strong>Bypassing the bashing limit:</strong> 1 day with VM for a first violation and up to 3 days with VM for a repeat.</li><li><strong>Insults:</strong> at least 1 day without VM; repeated violations increase the duration to 3, 7 and 14 days, up to termination of access.</li><li><strong>Spam and flooding:</strong> 1 day without VM for a first violation and 3 days without VM for a repeat; further violations may result in termination of access.</li><li><strong>Multiple accounts, violations of sitting conditions, account sales, exploiting errors, prohibited automation, real-life threats and prohibited content:</strong> suspension up to termination of game access.</li></ul><p>The administration records the reason and duration of each suspension. Suspension and account deletion are separate actions: automatic deletion after a fixed period is not part of the penalties listed here. Responsibility depends on participation in a violation; alliance membership alone does not prove involvement.</p></div></section><section class="content-article-section"><h2>11. Credits and paid features</h2><div class="content-article-section-body"><p>Credits and paid features are used under the conditions shown in the relevant interface sections. They do not permit rule violations or exempt players from suspension. Before using a service, review its price, effect and duration, where applicable.</p></div></section><section class="content-article-section"><h2>12. Application and changes</h2><div class="content-article-section-body"><p>Playing the game means accepting these rules and the <a href="/content/agreement">user agreement</a>. Not knowing a rule does not excuse a violation.</p><p>The current rules are published on this page. Changes and their effective dates are announced in game at least 2 weeks in advance. Urgent measures to protect the game and minor clarifications may have a shorter notice period, stated in the announcement. If wording has more than one possible interpretation, ask Support before taking the disputed action.</p></div></section></div>');
INSERT INTO `contents` (`title_ru`, `alias`, `html_ru`, `title_en`, `html_en`) VALUES ('Помощь', 'help', '<div class="content-article"><p class="content-article-intro">XNova — космическая стратегия о развитии собственной империи. Добывайте ресурсы, исследуйте технологии, заселяйте планеты и управляйте флотом вместе с союзниками или самостоятельно.</p><section class="content-article-section" id="help-contents"><h2>Содержание</h2><div class="content-article-section-body"><ol><li><a href="#help-start">Первые шаги</a></li><li><a href="#help-strategy">Стратегия новичка: быстрый старт</a></li><li><a href="#help-races">Фракции и их корабли</a></li><li><a href="#help-economy">Ресурсы, энергия и хранилища</a></li><li><a href="#help-development">Постройки и исследования</a></li><li><a href="#help-planets">Колонизация и военные базы</a>: <a href="#help-colonization">порядок действий</a>, <a href="#help-planet-properties">размер, температура и добыча</a></li><li><a href="#help-fleet">Корабли и отправка флота</a></li><li><a href="#help-missions">Миссии флота</a></li><li><a href="#help-expeditions">Экспедиции</a></li><li><a href="#help-combat">Разведка, бой и оборона</a></li><li><a href="#help-safety">Защита новичков и сохранение флота</a></li><li><a href="#help-moons">Луны, фаланга и врата</a></li><li><a href="#help-alliance">Альянсы и совместные действия</a></li><li><a href="#help-rewards">Задания, опыт и ежедневный бонус</a></li><li><a href="#help-credits">Кредиты, торговля и офицеры</a></li><li><a href="#help-statistics">Рейтинги и рекорды</a></li><li><a href="#help-tools">Общение и полезные разделы</a></li><li><a href="#help-vacation">Настройки и режим отпуска</a></li><li><a href="#help-faq">Частые вопросы</a></li></ol><p>Стоимость, время и доступность действий зависят от ваших технологий, фракции, офицеров и настроек вселенной. Проверяйте значения в интерфейсе перед подтверждением. Требования к объектам собраны в разделе <a href="/tech">«Технологии»</a>.</p></div></section><section class="content-article-section" id="help-start"><h2>1. Первые шаги</h2><div class="content-article-section-body"><ol><li>После выбора фракции откройте <a href="/overview">«Обзор»</a>: здесь видны состояние выбранного владения и события флота. Перед строительством или отправкой кораблей проверяйте, какая планета или луна выбрана.</li><li>Откройте <a href="/quests">«Задания»</a>, прочитайте условия первых задач и следуйте подсказкам. Выполненную задачу нужно завершить на её странице, чтобы получить награду.</li><li>Развивайте рудники металла и кристалла, синтезатор дейтерия и солнечную батарею. Поддерживайте достаточную выработку энергии и расширяйте хранилища.</li><li>Постройте лабораторию и верфь. Исследуйте требования к транспортам, шпионским зондам и колонизатору; затем выбирайте между ростом добычи, освоением новых планет и военными вылетами.</li><li>Перед первым нападением разведайте цель и проверьте состав флота в <a href="/sim">симуляторе боя</a>. Заранее продумайте возвращение кораблей и сбор обломков.</li></ol><p>Экономическое и военное развитие можно совмещать. Шахты дают постоянный доход, колонии расширяют производство, а атаки и экспедиции требуют внимания и связаны с риском потерь.</p></div></section><section class="content-article-section" id="help-strategy"><h2>2. Стратегия новичка: быстрый старт</h2><div class="content-article-section-body"><p>Для первого аккаунта разумная цель — наладить добычу, получить транспорт и освоить вторую планету. Ниже — рекомендуемый маршрут для XNova, а не обязательный порядок каждого клика. Темп зависит от скорости вселенной, фракции, соседей и времени на игру.</p><h3>Маршрут от первых шахт до колонии</h3><ol><li><strong>Заберите первую награду.</strong> Откройте задание «Основное снабжение»: доведите рудник металла до уровня 4, кристалла — до 2, солнечную батарею — до 4. Завершите задание и вложите награду в следующий этап.</li><li><strong>Подготовьте инфраструктуру.</strong> Для второго задания нужны синтезатор дейтерия 2, фабрика роботов 2, верфь 1 и одна ракетная установка. Затем ориентируйтесь на добывающие здания <strong>10/7/5</strong> — металл/кристалл/дейтерий: это условия третьего задания. Повышайте выработку энергии по мере роста потребления.</li><li><strong>Получите первый транспорт.</strong> Постройте лабораторию 1, изучите энергетическую технологию 1 и ракетный двигатель 2, улучшите верфь до 2 и постройте Малый транспорт. Завершите четвёртое задание. Следующие транспорты заказывайте под объём перевозок, сохраняя дейтерий на полёты.</li><li><strong>Выберите ближайшую цель развития.</strong> Для разведки откройте <a href="/tech/210">Шпионский зонд</a>: нужны верфь 3, шпионаж 2 и ракетный двигатель 3. Для расширения идите по <a href="#help-colonization">пути к колонизатору</a>. Исследуйте то, что будете использовать следующим действием.</li><li><strong>Запустите вторую экономику.</strong> Накопите на требования, колонизатор, топливо и начальные постройки колонии. Освойте удобную для снабжения позицию, доставьте ресурсы и развивайте добычу. Не нужно ждать заполнения всех полей главной планеты.</li></ol><p>Открывайте очередное <a href="/quests">задание</a> до выполнения его действий. Награда за вторую планету — Архитектор на 3 дня — доступна после завершения предыдущих заданий цепочки. Колонизировать можно и раньше, как только выполнены требования технологии и флота.</p><h3>Три варианта развития</h3><ul><li><strong>Шахтёр — для редких входов.</strong> Вкладывайте основную часть ресурсов в добычу, энергию и колонии. Расширяйте склады перед долгим отсутствием, поддерживайте транспорт для снабжения. Боевые корабли и высокие уровни вспомогательных зданий покупайте под конкретную задачу. Разумный первый выбор места — центральные позиции с запасом полей; холодные колонии требуют отдельного плана энергоснабжения.</li><li><strong>Налётчик — для частых входов.</strong> После базовой экономики откройте зонды и транспорты. Ищите доступные цели, в том числе неактивных игроков, проверяйте свежие отчёты и <a href="/sim">симуляцию</a>. Размер группы определяйте по обороне и добыче. Считайте прибыль после топлива и ожидаемых потерь; неактивность не означает отсутствие защиты. Добычу вкладывайте в шахты и расширение.</li><li><strong>Смешанный путь — для знакомства с игрой.</strong> Развивайте добычу по заданиям, держите небольшой транспортный флот и добавляйте налёты только при понятной выгоде. Это позволяет освоить бой без зависимости всей экономики от успешных атак.</li></ul><h3>Как выбирать следующее улучшение</h3><p>Смотрите, какого ресурса не хватает для ближайшей цели. Ориентир 10/7/5 помогает пройти задание, но не является постоянной пропорцией шахт. Если развитие останавливает кристалл или дейтерий, усиливайте именно их добычу. Сравнивайте прирост дохода от дорогого уровня на главной планете и нескольких дешёвых уровней в колонии, учитывая затраты на энергию и доставку.</p><p>Не тратьте весь стартовый запас на оборону, большой боевой флот или исследования без ближайшего применения. Оборона нужна соразмерно местным угрозам, а кредиты стоит сохранять до понятной задачи: обмена дефицитного ресурса или полезного периода работы офицера.</p><h3>Перед выходом из игры</h3><ul><li>Проверьте задания и таймер ежедневного бонуса; награды получайте на нужной планете.</li><li>Запустите доступное строительство и исследование, проверьте энергию и запас места в хранилищах до следующего входа.</li><li>Сохраните ценный флот и груз подходящим полётом, согласовав прибытие со своим возвращением. Учитывайте <a href="#help-safety">видимость и риски маршрута</a>.</li><li>Экспедиции используйте как рискованное дополнение: возможна потеря всей группы. Не отправляйте туда единственный транспорт или ресурсы, необходимые для колонизации.</li></ul><p>Подходы к старту сопоставлены с <a href="https://gameforge.com/en-GB/games/ogame-beginner-guide.html">руководством Gameforge</a>, <a href="https://forum.origin.ogame.gameforge.com/forum/thread/34-getting-started-guide-to-be-refined/">Getting Started Guide</a> и <a href="https://board.en.ogame.gameforge.com/index.php?thread/821043-updated-the-ultimate-miner-guide-v-2/">The Ultimate Miner Guide</a>. Приведённые здесь уровни, награды и ограничения адаптированы под XNova.</p></div></section><section class="content-article-section" id="help-races"><h2>3. Фракции и их корабли</h2><div class="content-article-section-body"><p>В XNova четыре фракции. Их бонусы действуют на всю империю, а уникальные корабли открываются после выполнения требований верфи и исследований.</p><ul><li><strong>Конфедерация — Корвет.</strong> Бонус к добыче металла и энергии солнечных спутников, ускоренное строительство кораблей.</li><li><strong>Бионики — Перехватчик.</strong> Бонус к добыче дейтерия, вместимости хранилищ и энергии солнечных спутников, сниженная стоимость кораблей.</li><li><strong>Сайлоны — Дредноут.</strong> Бонус к добыче всех трёх ресурсов, более дешёвые здания и оборона, ускоренное строительство зданий.</li><li><strong>Древние — Корсар.</strong> Бонус к добыче кристалла, энергии электростанций и скорости флота, сниженная стоимость исследований.</li></ul><p>Точные бонусы доступны в разделе <a href="/race">«Фракция»</a>. Для смены фракции завершите очереди на всех владениях и дождитесь возвращения собственных флотов. Сначала используются оставшиеся бесплатные смены, затем смена стоит 100 кредитов.</p><p><strong>При смене фракции все расовые корабли во владениях удаляются.</strong> Учитывайте это до подтверждения перехода.</p></div></section><section class="content-article-section" id="help-economy"><h2>4. Ресурсы, энергия и хранилища</h2><div class="content-article-section-body"><ul><li><strong>Металл</strong> нужен прежде всего для зданий, кораблей и обороны.</li><li><strong>Кристалл</strong> используется в строительстве и многих исследованиях.</li><li><strong>Дейтерий</strong> нужен для технологий, топлива флота, работы термоядерного реактора и сканирования фалангой.</li><li><strong>Энергия</strong> обеспечивает производство. Она не накапливается в трюмах и не перевозится транспортами.</li></ul><p>В разделе <a href="/resources">«Ресурсы»</a> показаны добыча, потребление и загрузка производственных объектов. При дефиците энергии эффективность добычи снижается. Можно менять загрузку отдельных объектов и включать или отключать производство во всей империи.</p><p>Солнечная батарея даёт энергию без расхода топлива. Термоядерный реактор расходует дейтерий. Солнечные спутники не занимают строительных полей, но могут погибнуть в бою; их выработка зависит от температуры. На холодных планетах выгоднее добывать дейтерий, на тёплых спутники дают больше энергии.</p><p>У каждого владения собственные запасы. Перевозите ресурсы флотом, если они нужны в другом месте. При заполнении хранилища прекращается накопление соответствующего ресурса от добычи: расходуйте запас или улучшайте склад. Луны и военные базы собственной добычи не имеют и нуждаются в снабжении.</p></div></section><section class="content-article-section" id="help-development"><h2>5. Постройки и исследования</h2><div class="content-article-section-body"><p><a href="/buildings">Постройки</a> развиваются отдельно на каждом владении. Уровни зданий занимают поля; доступное место видно в обзоре. Терраформер расширяет пространство на планете, лунная база — на луне. Набор разрешённых зданий зависит от типа владения.</p><p>Фабрика роботов и фабрика нанитов ускоряют развитие. Верфь производит <a href="/shipyard">корабли</a>, а в разделе <a href="/defense">«Оборона»</a> заказываются защитные сооружения и ракеты. Производство кораблей и обороны использует общую очередь верфи. Размер очереди зданий зависит от настроек вселенной и бонуса Архитектора.</p><p><a href="/research">Исследования</a> действуют на весь аккаунт. Одновременно выполняется одно исследование на весь аккаунт. Для запуска нужны лаборатория подходящего уровня и ресурсы на выбранной планете. Компьютерная технология увеличивает число одновременных полётов, двигатели влияют на скорость кораблей, боевые технологии усиливают вооружение, щиты и броню. М.И.С. позволяет использовать несколько лабораторий для ускорения исследований.</p><p>Если объект недоступен, откройте его карточку или <a href="/tech">дерево технологий</a>: проверьте необходимые уровни, фракцию и тип владения. Стоимость следующего уровня и время выполнения отображаются до запуска.</p></div></section><section class="content-article-section" id="help-planets"><h2>6. Колонизация и военные базы</h2><div class="content-article-section-body"><p>В <a href="/galaxy">галактике</a> адрес задаётся как [галактика:система:позиция]. Планета, её луна и поле обломков могут иметь одинаковые координаты, но это разные цели: всегда проверяйте выбранный тип.</p><h3 id="help-colonization">Колонизация: как основать новую планету</h3><p>Колония — ещё одна ваша планета с собственными ресурсами, постройками и очередями производства. Она принадлежит тому же аккаунту и использует уже изученные технологии. Колонизация осваивает свободную позицию; захватить чужую планету этой миссией нельзя.</p><h3>Что нужно для первого колонизатора</h3><ul><li><a href="/tech/150">Технология колонизации</a> не ниже 1-го уровня. Для её изучения нужны лаборатория 3-го уровня, броня космических кораблей 2-го уровня и энергетическая технология 5-го уровня.</li><li><a href="/tech/208">Колонизатор</a>: верфь 4-го уровня, импульсный двигатель 3-го уровня и технология колонизации 1-го уровня.</li><li>Ресурсы на постройку корабля, дейтерий для полёта и свободный слот флота. Базовая цена колонизатора — 10 000 металла, 20 000 кристалла и 10 000 дейтерия; итоговая цена с бонусами показана на верфи.</li><li>Свободное место в лимите обычных планет. Наличие корабля само по себе не разрешает превысить этот лимит.</li></ul><h3>Сколько планет можно иметь</h3><p>Общее число обычных планет, включая главную, не может превышать <strong>уровень технологии колонизации + 1</strong> и предел вселенной. Например, 1-й уровень позволяет иметь главную планету и одну колонию, 2-й — главную и две колонии. По умолчанию предел вселенной равен 9 планетам. Луны и военные базы считаются отдельно.</p><p>Лимит и занятость позиции проверяются при прибытии. Если отправить несколько колонизаторов на разные позиции при одном свободном месте в лимите, после основания первой колонии остальные уже не смогут создать новые планеты.</p><h3>Как выбрать место</h3><p>В <a href="/galaxy">галактике</a> найдите свободную обычную позицию. При стандартных настройках для колоний предназначены позиции 1–15, а 16-я используется для экспедиций. Пустое поле обломков или отсутствие луны у занятой планеты не делает позицию свободной для колонизации.</p><p>Ближайшую колонию проще снабжать: короткие перелёты позволяют быстрее перемещать ресурсы и флот. При выборе учитывайте соседей, температуру и будущую специализацию. Центральные позиции обычно дают больше строительных полей, холодные дальние планеты выгодны для добычи дейтерия, а на тёплых выше выработка солнечных спутников.</p><p>Число полей и температура определяются случайно в диапазоне выбранной позиции. Точный размер станет известен после основания; одна и та же позиция не гарантирует одинаковые планеты. Поля ограничивают развитие зданий, поэтому оценивайте их запас до крупных вложений в колонию.</p><h3 id="help-planet-properties">Позиция, размер, температура и производство</h3><p><strong>Позиция в системе задаёт диапазоны размера и температуры.</strong> При основании колонии число полей и максимальная температура выбираются случайно в диапазонах её позиции. Номер галактики и системы сам по себе бонусов к добыче или энергии не даёт.</p><p>В «Обзоре» указан <strong>диаметр</strong> планеты; радиус равен половине диаметра. При создании колонии связь с начальным числом полей F такая: <strong>D = округление вниз(1 000 × √F) км; R = D / 2</strong>. Например, 225 полей соответствуют диаметру 15 000 км и радиусу 7 500 км. Сам размер напрямую не повышает добычу и энергию: он даёт место для развития зданий. Терраформер добавляет поля, поэтому после расширения нельзя определять доступное место только по диаметру.</p><p>Таблица описывает обычные новые колонии при стандартном множителе размера ×1; главная планета и военные базы получают число полей по отдельным настройкам. Множитель размера вселенной меняет начальное число полей и связанный с ним диаметр. <strong>T — максимальная температура</strong>, а не средняя: в обзоре показан интервал от T − 40 до T. В таблице приведён диапазон возможных значений именно T.</p><div class="game-table-wrap content-table-wrap" role="region" aria-labelledby="colony-table-caption" tabindex="0"><table class="game-table content-table"><caption id="colony-table-caption">Параметры колоний по позиции в системе</caption><thead><tr><th scope="col">Позиция</th><th scope="col">Начальные поля</th><th scope="col">T, °C</th><th scope="col">Множитель дейтерия</th><th scope="col">Энергия одного спутника</th></tr></thead><tbody><tr><th scope="row">1</th><td>95–128</td><td>220…260</td><td>0,40–0,56</td><td>60–66</td></tr><tr><th scope="row">2</th><td>97–130</td><td>170…210</td><td>0,60–0,76</td><td>51–58</td></tr><tr><th scope="row">3</th><td>98–147</td><td>120…160</td><td>0,80–0,96</td><td>43–50</td></tr><tr><th scope="row">4</th><td>123–223</td><td>70…110</td><td>1,00–1,16</td><td>35–41</td></tr><tr><th scope="row">5</th><td>148–230</td><td>60…100</td><td>1,04–1,20</td><td>33–40</td></tr><tr><th scope="row">6</th><td>148–246</td><td>50…90</td><td>1,08–1,24</td><td>31–38</td></tr><tr><th scope="row">7</th><td>141–293</td><td>40…80</td><td>1,12–1,28</td><td>30–36</td></tr><tr><th scope="row">8</th><td>169–266</td><td>30…70</td><td>1,16–1,32</td><td>28–35</td></tr><tr><th scope="row">9</th><td>161–258</td><td>20…60</td><td>1,20–1,36</td><td>26–33</td></tr><tr><th scope="row">10</th><td>154–244</td><td>10…50</td><td>1,24–1,40</td><td>25–31</td></tr><tr><th scope="row">11</th><td>148–224</td><td>0…40</td><td>1,28–1,44</td><td>23–30</td></tr><tr><th scope="row">12</th><td>136–191</td><td>-10…30</td><td>1,32–1,48</td><td>21–28</td></tr><tr><th scope="row">13</th><td>109–141</td><td>-50…-10</td><td>1,48–1,64</td><td>15–21</td></tr><tr><th scope="row">14</th><td>81–113</td><td>-90…-50</td><td>1,64–1,80</td><td>8–15</td></tr><tr><th scope="row">15</th><td>65–94</td><td>-130…-90</td><td>1,80–1,96</td><td>1–8</td></tr></tbody></table></div><p>Множитель дейтерия в таблице — температурная часть формулы, а энергия спутника указана при загрузке 100%, без бонусов фракции и офицеров. Значения в каждом диапазоне не обязаны выпадать вместе: размер и температура выбираются отдельно.</p><h3>Как температура влияет на дейтерий</h3><p>При уровне синтезатора L, загрузке 100% и достаточной энергии базовая добыча за час равна <strong>10 × L × 1,1<sup>L</sup> × (1,44 − 0,004 × T)</strong>. Затем учитываются скорость добычи вселенной, бонусы фракции и Геолога, загрузка и обеспеченность энергией; в расчётах применяется округление вниз. Расход дейтерия реактором уменьшает итоговый доход.</p><p>Чем ниже T, тем выше добыча при том же уровне синтезатора. При T = +100 °C температурный множитель равен 1,04, а при T = −100 °C — 1,84: при равных остальных условиях холодная планета даёт примерно на 77% больше дейтерия до округления. Потребление энергии самим синтезатором от температуры не зависит: при загрузке 100% оно равно округлению вниз(20 × L × 1,1<sup>L</sup>).</p><h3>Как температура влияет на энергию</h3><p>Базовая выработка <strong>одного солнечного спутника = округление вниз((T + 140) / 6)</strong>. При T = +100 °C это 40 энергии, при T = −100 °C — только 6. Выработка группы зависит от числа спутников, их загрузки и бонусов фракции и Инженера. Спутники уязвимы в бою, поэтому учитывайте возможность потери этого источника энергии.</p><p><strong>Солнечная батарея и термоядерный реактор от температуры не зависят.</strong> При загрузке 100% базовая выработка солнечной батареи уровня L равна 20 × L × 1,1<sup>L</sup>, реактора — 30 × L × (1,05 + 0,01 × E)<sup>L</sup>, где E — уровень энергетической технологии. Итог учитывает округление, загрузку и бонусы энергии. Реактор расходует дейтерий, а энергетическая технология усиливает именно его базовую выработку.</p><p>Добыча металла и кристалла напрямую от температуры и диаметра не зависит. Практический выбор: центральные позиции обычно удобнее для большой промышленной колонии; дальние холодные — для дейтерия, но требуют более серьёзного энергоснабжения; близкие тёплые дают эффективные спутники, зато хуже подходят для дейтерия. Большая планета не обязательно холодная или богатая: оценивайте поля и температуру отдельно.</p><h3>Отправка по шагам</h3><ol><li>Постройте колонизатор в <a href="/shipyard">верфи</a> и выберите владение, где он находится.</li><li>Откройте <a href="/fleet">«Флот»</a>, укажите один колонизатор. При необходимости добавьте транспорты с запасом ресурсов для начала строительства.</li><li>Введите координаты свободной позиции и выберите тип цели <strong>«Планета»</strong>.</li><li>Выберите миссию <strong>«Колонизировать»</strong>, скорость и груз. Проверьте время прибытия, расход топлива и вместимость.</li><li>Отправьте флот и дождитесь сообщения о результате. Отправка не резервирует позицию: другой игрок может прибыть раньше.</li></ol><h3>Что произойдёт при прибытии</h3><p>При успехе <strong>один колонизатор расходуется</strong>. Все остальные корабли, включая дополнительные колонизаторы, и доставленные ресурсы остаются на новой планете. Автоматического обратного полёта нет. Несколько колонизаторов в одном флоте не создают несколько колоний за одну миссию.</p><p>Если место уже занято или достигнут лимит планет, колонизация не состоится и флот вернётся. Причина будет указана в <a href="/messages">сообщениях</a>. При необходимости исследуйте следующий уровень технологии или выберите другую свободную позицию.</p><h3>Первые действия в колонии</h3><p>Выберите новую планету в списке владений и откройте <a href="/overview">«Обзор»</a>: проверьте поля, температуру и запасы, задайте название. Начните с энергии и добычи, затем развивайте фабрику роботов, склады и нужную инфраструктуру. Здания главной планеты не копируются в колонию.</p><p>Для дальнейшего снабжения используйте «Транспорт»: корабли выгрузят ресурсы и вернутся. Для переноса флота в колонию используйте «Оставить»: корабли останутся в пункте назначения. Состояние всех планет удобно сравнивать в разделе <a href="/empire">«Империя»</a>.</p><h3>Военные базы</h3><p>Для миссии «Создать базу» нужна Передвижная база и свободная позиция. Максимальное число военных баз равно уровню исследования «Военная база». При создании расходуется одна Передвижная база, сопровождение и груз остаются на новом владении.</p><p>Военная база — опорный пункт с ограниченным набором построек, в том числе вратами и ракетной шахтой. Она не заменяет добывающую колонию: ресурсы нужно привозить. Сводку по владениям удобно смотреть в разделе <a href="/empire">«Империя»</a>.</p></div></section><section class="content-article-section" id="help-fleet"><h2>7. Корабли и отправка флота</h2><div class="content-article-section-body"><ul><li><strong>Малый и Большой транспорты</strong> перевозят ресурсы и вывозят добычу. Учитывайте их слабое вооружение при атаках.</li><li><strong>Лёгкий и Тяжёлый истребители, Крейсер, Линкор и Линейный крейсер</strong> составляют боевые группы. Их полезность зависит от противника, технологий и скорострела.</li><li><strong>Бомбардировщик и Уничтожитель</strong> помогают бороться с укреплёнными целями; состав противника всё равно нужно проверять в симуляторе.</li><li><strong>Звезда смерти</strong> — тяжёлый и медленный корабль, необходимый для попытки уничтожить луну.</li><li><strong>Переработчик, Шпионский зонд, Колонизатор и Передвижная база</strong> нужны для своих специальных миссий. Расовые корабли дополняют боевой флот.</li><li><strong>Солнечный спутник</strong> производит энергию на орбите и не участвует в обычных полётах.</li></ul><p>В разделе <a href="/fleet">«Флот»</a> выберите корабли, координаты, тип цели, скорость, миссию и груз. Перед отправкой проверьте время прибытия и возвращения, расход дейтерия и свободный трюм. Скорость группы ограничивает самый медленный корабль; топливо занимает часть вместимости.</p><p>Базовый лимит полётов — один плюс уровень компьютерной технологии. Активный Адмирал добавляет ещё два слота. Полёты на разных заданиях используют общий лимит; у экспедиций есть и отдельное ограничение. Для повторяющихся маршрутов используйте <a href="/fleet/shortcut">закладки координат</a>.</p></div></section><section class="content-article-section" id="help-missions"><h2>8. Миссии флота</h2><div class="content-article-section-body"><ul><li><strong>Атаковать.</strong> Бой у чужого владения с возможным захватом части ресурсов. Выжившие корабли возвращаются с добычей в пределах трюма.</li><li><strong>Объединить.</strong> Присоединение к совместной атаке. Группу и приглашения настраивают через управление атакующим флотом.</li><li><strong>Транспорт.</strong> Доставка ресурсов с последующим возвращением кораблей. Подходит и для снабжения собственных владений.</li><li><strong>Оставить.</strong> Перебазирование флота и груза на своё владение. После успешного прибытия автоматического обратного полёта нет.</li><li><strong>Удерживать.</strong> Временное размещение флота у другого игрока для участия в обороне. Удержание требует дополнительного дейтерия; после него флот возвращается.</li><li><strong>Шпионаж.</strong> Получение сведений о чужом владении с помощью зондов. Зонды могут быть уничтожены.</li><li><strong>Колонизировать.</strong> Основание обычной колонии с помощью колонизатора.</li><li><strong>Переработать.</strong> Сбор металла и кристалла из поля обломков переработчиками. Выбирайте именно поле обломков, а не планету.</li><li><strong>Уничтожить.</strong> Попытка разрушить чужую луну Звёздами смерти после победы в бою. Возможны неудача и гибель отправленного флота.</li><li><strong>Создать базу.</strong> Основание военной базы с помощью Передвижной базы.</li><li><strong>Экспедиция.</strong> Исследование дальней позиции системы со случайным результатом.</li></ul><p><strong>Межпланетная атака</strong> запускается отдельно ракетами через галактику: это удар по обороне, а не перевозка кораблей. Доступность обычных миссий определяется составом флота, типом цели, исследованиями и ограничениями отправки.</p><p>Передача ресурсов одному другому игроку ограничена одной отправкой за последние 24 часа и тремя за последние 7 дней. Транспорт игроку, отсутствовавшему более 7 дней, недоступен. Передачи между своими владениями не подпадают под эти ограничения. Также соблюдайте <a href="/content/rules">правила обмена и помощи</a>.</p></div></section><section class="content-article-section" id="help-expeditions"><h2>9. Экспедиции</h2><div class="content-article-section-body"><p>Изучите экспедиционную технологию и выберите позицию сразу после последней обычной планеты системы: при 15 планетных позициях это позиция 16. Флот не может состоять только из шпионских зондов.</p><p>Выберите доступную длительность исследования. Уровень технологии увеличивает предельное время экспедиции и число экспедиционных групп. Общий лимит полётов тоже должен иметь свободное место.</p><p>Экспедиция может принести ресурсы, кредиты или корабли, закончиться без находок, задержаться, вступить в бой или исчезнуть целиком. Оставляйте место для находок и отправляйте только те силы, потерю которых готовы пережить. Результат приходит в сообщения; возвращение может произойти позже первоначального расчёта.</p></div></section><section class="content-article-section" id="help-combat"><h2>10. Разведка, бой и оборона</h2><div class="content-article-section-body"><p>Полнота шпионского отчёта зависит от числа зондов и разницы уровней шпионажа, включая бонусы. Отсутствие раздела в отчёте не означает отсутствия флота или обороны. Отчёт показывает состояние на момент разведки: к прибытию атакующих сил оно может измениться.</p><p>Бой учитывает состав сторон, вооружение, щиты, броню и скорострел — возможность дополнительных выстрелов по определённым типам целей. Универсального непобедимого состава нет. В <a href="/sim">симуляторе</a> сравнивайте потери, добычу и обломки; расчёт не гарантирует такой же исход реального боя.</p><p>Ракетные установки и лазеры создают массовую оборону, пушки Гаусса, ионные и плазменные орудия дополняют её, щитовые купола усиливают защиту. После обычного боя часть обороны может восстановиться. Точные доли восстановления и образования обломков зависят от настроек и бонусов.</p><p>Межпланетные ракеты поражают оборону в пределах досягаемости в своей галактике. Для запуска нужны ракетная шахта не ниже 4-го уровня и импульсный двигатель; он же увеличивает дальность. Ракеты-перехватчики автоматически противодействуют ракетному удару. Вместимость шахты ограничивает запас ракет.</p><p>После боя изучите отчёт в <a href="/messages">сообщениях</a> и отправьте переработчики, если рассчитываете на обломки. Победа не закрепляет поле за победителем: его могут собрать другие игроки.</p></div></section><section class="content-article-section" id="help-safety"><h2>11. Защита новичков и сохранение флота</h2><div class="content-article-section-body"><p>При включённой защите новичков отправка враждебного флота к активной цели ниже порога очков блокируется. Также проверяется, не превосходит ли отправитель цель по очкам больше допустимого множителя. По умолчанию порог составляет 5 000 очков, множитель — 5; во вселенной они могут быть изменены.</p><p>Проверки затрагивают атаки, совместные атаки, шпионаж, уничтожение луны и удержание; для удержания у своего альянса есть исключение. Для цели, отсутствовавшей более 7 дней или заблокированной, эти проверки защиты новичков отключаются. Ракетный удар имеет отдельные условия, поэтому защита новичков не равнозначна полной неуязвимости.</p><p>Не оставляйте надолго крупные запасы и ценный флот без присмотра. Для сохранения кораблей на время отсутствия выбирайте подходящий полёт с грузом и рассчитывайте прибытие на время, когда сможете вернуться в игру. Учитывайте фалангу, возможность отзыва и конечную точку: после прибытия флот снова может стать целью. Экспедиция с риском полной гибели для безопасного хранения не подходит.</p></div></section><section class="content-article-section" id="help-moons"><h2>12. Луны, фаланга и врата</h2><div class="content-article-section-body"><p>Луна может появиться после боя у обычной планеты, если луны ещё нет. Шанс рассчитывается по обломкам этого боя и ограничен настройками вселенной; активный Адмирал у защитника повышает верхний предел. Даже максимальный шанс не гарантирует успех. Создание луны не собирает поле обломков за вас.</p><p>На луне нет добычи: доставляйте ресурсы транспортами. Лунная база увеличивает число строительных полей. Луна может быть атакована и уничтожена, поэтому её наличие не делает флот неуязвимым.</p><h3>Сенсорная фаланга</h3><p>Работает с выбранной луны и сканирует планеты в своей галактике. Дальность в каждую сторону равна квадрату уровня минус один: уровень 1 — своя система, уровень 2 — до 3 систем, уровень 3 — до 8. Одно сканирование расходует 5 000 дейтерия на луне.</p><p>Фаланга показывает доступные ей перемещения и времена прибытия, связанные со сканируемой планетой. Она не раскрывает все полёты во вселенной: например, перелёты между лунами и с луны к обломкам ей не видны.</p><h3>Межгалактические врата</h3><p>Врата мгновенно перемещают корабли между собственными лунами и военными базами, где они построены и готовы к работе. Выбор точки перехода доступен при отправке флота. Ресурсы через врата не перевозятся. После перехода оба устройства перезаряжаются; более высокий уровень сокращает ожидание.</p></div></section><section class="content-article-section" id="help-alliance"><h2>13. Альянсы и совместные действия</h2><div class="content-article-section-body"><p>В разделе <a href="/alliance">«Альянс»</a> можно создать объединение или подать заявку в существующее. Альянс предоставляет список участников, внутренний чат, ранги с правами, управление заявками и дипломатию. Доступ к управлению зависит от вашего ранга.</p><p>Для совместной атаки создайте группу у отправленного атакующего флота, пригласите участников и присоединяйте силы через миссию «Объединить». Проверяйте доступность группы и итоговое время прибытия: присоединение флотов ограничено условиями полёта.</p><p>Для совместной обороны используется «Удерживать». Склад альянса позволяет снабжать удерживаемые флоты дейтерием. Дипломатические соглашения могут ограничивать атаки. Членство в альянсе не отменяет правил передачи ресурсов.</p></div></section><section class="content-article-section" id="help-rewards"><h2>14. Задания, опыт и ежедневный бонус</h2><div class="content-article-section-body"><p><a href="/quests">Задания</a> знакомят с механиками и дают награды: ресурсы, кредиты, уровни объектов, корабли, оборону или время действия офицеров. Часть заданий открывается после предыдущих задач или достижения нужного уровня развития.</p><p>Откройте задание до выполнения, прочитайте условия и заберите награду после их выполнения. Условия, связанные с постройками и кораблями, могут проверяться на выбранном владении; ресурсы и локальные награды начисляются туда же. Если задача не завершается, проверьте выбранную планету и все предварительные требования.</p><p>Промышленный опыт начисляется за развитие соответствующих зданий, военный — по результатам боёв. Это отдельные показатели от рейтинговых очков. Повышение уровня приносит кредиты и может открыть новые задания; прогресс виден в обзоре.</p><p>Ежедневный бонус нужно получать вручную. Следующее получение доступно через 24 часа, ресурсы поступают на выбранное владение. Последовательные получения увеличивают награду и со второго получения серии дают дополнительный кредит. Длительный пропуск сбрасывает серию; ориентируйтесь на таймер бонуса.</p></div></section><section class="content-article-section" id="help-credits"><h2>15. Кредиты, торговля и офицеры</h2><div class="content-article-section-body"><p>Кредиты — общая валюта аккаунта. Их можно получить за уровни, некоторые задания, находки экспедиций, продолжение серии ежедневных бонусов и рефералов. Раздел <a href="/credits">«Кредиты»</a> содержит доступные способы пополнения.</p><p><a href="/merchant">Торговец</a> обменивает ресурсы выбранного владения по показанному курсу. Один обмен стоит 1 кредит. В разделе «Ресурсы» на обычной планете также доступна покупка показанного набора ресурсов за 10 кредитов с ожиданием 48 часов до следующей покупки на этой планете.</p><p><a href="/officiers">Офицеры</a> нанимаются на ограниченное время. Повторный найм действующего офицера продлевает срок, а не удваивает его эффект.</p><ul><li><strong>Геолог</strong> повышает добычу и вместимость хранилищ.</li><li><strong>Адмирал</strong> добавляет слоты флота, ускоряет корабли, снижает их стоимость и влияет на лунные операции.</li><li><strong>Инженер</strong> повышает выработку энергии, удешевляет оборону и помогает снизить потери.</li><li><strong>Технократ</strong> ускоряет исследования и даёт бонус к шпионажу.</li><li><strong>Архитектор</strong> расширяет очередь зданий и ускоряет строительство зданий, кораблей и обороны.</li><li><strong>Метафизик</strong> снижает расход топлива в полёте.</li><li><strong>Наёмник</strong> усиливает вооружение, щиты и броню.</li></ul><p>Проверяйте точные эффекты, цену и срок найма в карточке офицера. В разделе <a href="/referrals">«Рефералы»</a> доступна ссылка для приглашения друзей и сведения об их развитии; повышение уровней приглашённых игроков приносит награду пригласившему.</p></div></section><section class="content-article-section" id="help-statistics"><h2>16. Рейтинги и рекорды</h2><div class="content-article-section-body"><p><a href="/stats">Статистика</a> сравнивает игроков, альянсы и фракции по общим очкам, зданиям, исследованиям, флоту и обороне. Очки рассчитываются по базовой ресурсной стоимости имеющихся объектов и уровней: 1 000 ресурсов соответствуют одному очку. Запасы на складах сами по себе очков не дают.</p><p>Флот в полёте учитывается. Потери кораблей, снос зданий и утрата владений могут уменьшить результат. Рейтинги флота и исследований учитывают стоимость, а не только число кораблей или уровней. Статистика обновляется периодически, поэтому изменение места может появиться не сразу.</p><p><a href="/records">Рекорды</a> показывают достижения по отдельным объектам, а <a href="/hall">Зал славы</a> — крупные сражения. В настройках можно управлять участием в рекордах.</p></div></section><section class="content-article-section" id="help-tools"><h2>17. Общение и полезные разделы</h2><div class="content-article-section-body"><ul><li><a href="/messages">Сообщения</a> — личная переписка, результаты разведки, боёв и миссий. Здесь же можно пожаловаться на сообщение.</li><li><a href="/chat">Чат</a> — общение с другими игроками; внутренний чат альянса доступен отдельно.</li><li><a href="/friends">Друзья</a> и <a href="/search">поиск</a> помогают находить игроков и поддерживать контакты.</li><li><a href="/notes">Заметки</a> позволяют сохранять собственные записи.</li><li><a href="/logs">Боевые логи</a> позволяют сохранять отчёты для просмотра и обсуждения.</li><li><a href="/support">Поддержка</a> — обращения по ошибкам и игровым вопросам. Укажите координаты, время события и отчёт, если он есть.</li></ul><p>Перед торговлей, договорными боями и совместными действиями прочитайте <a href="/content/rules">правила XNova</a>. При недоступном входе используйте страницу <a href="/contacts">«Контакты»</a>.</p></div></section><section class="content-article-section" id="help-vacation"><h2>18. Настройки и режим отпуска</h2><div class="content-article-section-body"><p>В <a href="/options">настройках</a> меняются язык, параметры интерфейса, почта и пароль. Сохраняйте доступ к привязанной почте: она нужна для восстановления аккаунта.</p><p>Для длительного отсутствия включите режим отпуска. Перед этим должны завершиться все очереди аккаунта и вернуться собственные флоты. Режим останавливает добычу и ограничивает игровые действия; новые отправки флота к вашим владениям блокируются, кроме переработки обломков.</p><p><strong>Уже отправленные к вам флоты не отменяются.</strong> Отпуск не заменяет защиту от начавшейся атаки. Минимальный срок задаётся вселенной, по умолчанию это 2 дня. После указанного срока отпуск нужно отключить вручную. Затем проверьте загрузку производства в разделе «Ресурсы»: при входе в отпуск она выставляется в ноль.</p></div></section><section class="content-article-section" id="help-faq"><h2>19. Частые вопросы</h2><div class="content-article-section-body"><h3>Почему добыча низкая или остановилась?</h3><p>Проверьте энергию, заполнение складов, проценты загрузки и режим отпуска. На лунах и военных базах добычи нет; реактору нужен дейтерий.</p><h3>Почему не получается отправить флот?</h3><p>Проверьте свободные слоты, наличие кораблей и топлива, вместимость с учётом груза, координаты и тип цели. Для отдельных миссий нужны специальные корабли, технологии или приглашение в группу. Учитывайте отпуск, защиту новичков, дипломатию и ограничения передачи ресурсов.</p><h3>Почему не появилась колония или база?</h3><p>Прочитайте сообщение миссии: позицию могли занять до прибытия либо был достигнут лимит. Изучите соответствующую технологию и проверьте свободное место в империи до повторной отправки.</p><h3>Почему нельзя сменить фракцию или уйти в отпуск?</h3><p>Проверьте очереди на всех владениях и собственные флоты в полёте. Для смены фракции также нужна бесплатная попытка или достаточное число кредитов.</p><p><a href="#help-contents">Вернуться к содержанию</a></p></div></section></div>', 'Help', '<div class="content-article"><p class="content-article-intro">XNova is a space strategy game about building your own empire. Gather resources, research technologies, settle planets and command fleets on your own or with allies.</p><section class="content-article-section" id="help-contents"><h2>Contents</h2><div class="content-article-section-body"><ol><li><a href="#help-start">First steps</a></li><li><a href="#help-strategy">Beginner strategy: a fast start</a></li><li><a href="#help-races">Factions and their ships</a></li><li><a href="#help-economy">Resources, energy and storage</a></li><li><a href="#help-development">Buildings and research</a></li><li><a href="#help-planets">Colonization and military bases</a>: <a href="#help-colonization">steps</a>, <a href="#help-planet-properties">size, temperature and production</a></li><li><a href="#help-fleet">Ships and fleet dispatch</a></li><li><a href="#help-missions">Fleet missions</a></li><li><a href="#help-expeditions">Expeditions</a></li><li><a href="#help-combat">Espionage, combat and defense</a></li><li><a href="#help-safety">New player protection and fleet safety</a></li><li><a href="#help-moons">Moons, phalanxes and jump gates</a></li><li><a href="#help-alliance">Alliances and joint operations</a></li><li><a href="#help-rewards">Quests, experience and daily bonuses</a></li><li><a href="#help-credits">Credits, trading and officers</a></li><li><a href="#help-statistics">Rankings and records</a></li><li><a href="#help-tools">Communication and useful tools</a></li><li><a href="#help-vacation">Settings and vacation mode</a></li><li><a href="#help-faq">Common questions</a></li></ol><p>Costs, times and available actions depend on your technologies, faction, officers and universe settings. Check the values shown before confirming an action. Object requirements are listed in the <a href="/tech">technology tree</a>.</p></div></section><section class="content-article-section" id="help-start"><h2>1. First steps</h2><div class="content-article-section-body"><ol><li>After choosing a faction, open <a href="/overview">Overview</a> to see the selected location and fleet events. Check which planet or moon is selected before building or sending ships.</li><li>Open <a href="/quests">Quests</a>, read the first objectives and follow their hints. Once the conditions are met, complete the quest on its page to claim the reward.</li><li>Develop metal and crystal mines, a deuterium synthesizer and a solar plant. Keep energy production sufficient and expand storage.</li><li>Build a research laboratory and shipyard. Check the requirements for cargo ships, espionage probes and colony ships, then choose between increasing production, expanding to new planets and military operations.</li><li>Before attacking, scout the target and check your fleet in the <a href="/sim">battle simulator</a>. Plan the return flight and debris collection in advance.</li></ol><p>You can combine economic and military development. Mines provide steady income and colonies expand production, while attacks and expeditions require attention and carry a risk of losses.</p></div></section><section class="content-article-section" id="help-strategy"><h2>2. Beginner strategy: a fast start</h2><div class="content-article-section-body"><p>For a first account, a useful goal is steady production, a cargo ship and a second planet. This is a suggested XNova route rather than a mandatory order for every click. Progress depends on universe speed, faction, neighbors and the time you can spend playing.</p><h3>From your first mines to a colony</h3><ol><li><strong>Claim the first reward.</strong> Open the first supply quest: reach metal mine level 4, crystal mine level 2 and solar plant level 4. Complete it and invest the reward in the next stage.</li><li><strong>Prepare your infrastructure.</strong> The second quest requires a level 2 deuterium synthesizer, level 2 robotics factory, level 1 shipyard and one rocket launcher. Then aim for <strong>10/7/5</strong> in metal/crystal/deuterium production buildings, the third quest requirements. Increase energy output as consumption grows.</li><li><strong>Get your first cargo ship.</strong> Build laboratory level 1, research energy technology 1 and combustion drive 2, upgrade the shipyard to level 2 and build a Small Cargo. Complete the fourth quest. Order more cargo ships to meet actual hauling needs, keeping deuterium for flights.</li><li><strong>Choose your next objective.</strong> For scouting, unlock the <a href="/tech/210">Espionage Probe</a>: shipyard 3, espionage 2 and combustion drive 3. For expansion, follow the <a href="#help-colonization">colony ship requirements</a>. Research something you intend to use next.</li><li><strong>Start a second economy.</strong> Save for the prerequisites, colony ship, fuel and initial colony buildings. Settle a location that is convenient to supply, deliver resources and develop production. There is no need to fill every homeworld field first.</li></ol><p>Open each new <a href="/quests">quest</a> before performing its actions. The second-planet reward, an Architect for 3 days, becomes available after earlier quests in the chain are completed. You can colonize sooner once technology and fleet requirements are met.</p><h3>Three development paths</h3><ul><li><strong>Miner — for less frequent logins.</strong> Put most resources into production, energy and colonies. Expand storage before long absences and maintain cargo ships for supplies. Buy combat ships and higher support-building levels for a specific purpose. Central positions with room to build are a sensible first choice; cold colonies need a separate energy plan.</li><li><strong>Raider — for frequent logins.</strong> After establishing basic production, unlock probes and cargo ships. Find eligible targets, including inactive players, and check recent reports and <a href="/sim">simulations</a>. Choose fleet size for the defenses and available loot. Calculate profit after fuel and expected losses; inactivity does not mean no defenses. Reinvest loot in mines and expansion.</li><li><strong>Mixed approach — for learning.</strong> Develop production through quests, keep a small cargo fleet and add raids when the benefit is clear. This lets you learn combat without making the whole economy depend on successful attacks.</li></ul><h3>Choosing the next upgrade</h3><p>Identify which resource is holding back your next objective. The 10/7/5 target completes a quest; it is not a permanent mine ratio. If crystal or deuterium is the bottleneck, improve that production. Compare the additional income from one expensive homeworld level with several cheaper colony levels, including energy and delivery costs.</p><p>Avoid spending your entire starting stockpile on defenses, a large combat fleet or research with no immediate use. Match defenses to local threats, and keep credits until you have a clear purpose, such as exchanging a scarce resource or hiring an officer for a useful period.</p><h3>Before logging off</h3><ul><li>Check quests and the daily bonus timer; claim rewards at the intended location.</li><li>Start available construction and research, check energy and leave enough storage room until your next login.</li><li>Protect valuable ships and cargo with an appropriate flight timed for your return. Consider <a href="#help-safety">route visibility and risks</a>.</li><li>Treat expeditions as a risky supplement: an entire group can be lost. Do not send your only cargo ship or resources needed for colonization.</li></ul><p>Starting approaches were compared with the <a href="https://gameforge.com/en-GB/games/ogame-beginner-guide.html">Gameforge beginner guide</a>, <a href="https://forum.origin.ogame.gameforge.com/forum/thread/34-getting-started-guide-to-be-refined/">Getting Started Guide</a> and <a href="https://board.en.ogame.gameforge.com/index.php?thread/821043-updated-the-ultimate-miner-guide-v-2/">The Ultimate Miner Guide</a>. Levels, rewards and restrictions here are adapted to XNova.</p></div></section><section class="content-article-section" id="help-races"><h2>3. Factions and their ships</h2><div class="content-article-section-body"><p>XNova has four factions. Their bonuses apply throughout your empire, and unique ships become available once their shipyard and research requirements are met.</p><ul><li><strong>Confederation — Corvette.</strong> Bonuses to metal production and solar satellite energy, and faster ship construction.</li><li><strong>Bionics — Interceptor.</strong> Bonuses to deuterium production, storage capacity and solar satellite energy, with cheaper ships.</li><li><strong>Cylons — Dreadnought.</strong> Bonuses to all three mined resources, cheaper buildings and defenses, and faster building construction.</li><li><strong>Ancients — Corsair.</strong> Bonuses to crystal production, power plant energy and fleet speed, with cheaper research.</li></ul><p>See <a href="/race">Faction</a> for exact bonuses. To change faction, finish queues at every location and wait for your fleets to return. Remaining free changes are used first; subsequent changes cost 100 credits.</p><p><strong>Changing faction removes all faction ships at your locations.</strong> Account for this before confirming the change.</p></div></section><section class="content-article-section" id="help-economy"><h2>4. Resources, energy and storage</h2><div class="content-article-section-body"><ul><li><strong>Metal</strong> is used mainly for buildings, ships and defenses.</li><li><strong>Crystal</strong> is used in construction and many research projects.</li><li><strong>Deuterium</strong> is needed for technologies, fleet fuel, fusion reactors and phalanx scans.</li><li><strong>Energy</strong> powers production. It cannot be stockpiled in cargo holds or transported.</li></ul><p><a href="/resources">Resources</a> shows production, consumption and operating levels. An energy shortage reduces mining efficiency. You can adjust individual facilities or turn production on and off throughout the empire.</p><p>Solar plants produce energy without fuel. Fusion reactors consume deuterium. Solar satellites use no building fields but can be destroyed in combat; their output depends on temperature. Colder planets favor deuterium production, while warmer planets give more satellite energy.</p><p>Each location has its own stockpiles. Transport resources when they are needed elsewhere. When storage fills up, mining stops adding that resource: spend the stockpile or upgrade storage. Moons and military bases have no resource production and need supplies.</p></div></section><section class="content-article-section" id="help-development"><h2>5. Buildings and research</h2><div class="content-article-section-body"><p><a href="/buildings">Buildings</a> are developed separately at each location. Building levels occupy fields; Overview shows the space available. Terraformers expand planets, and lunar bases expand moons. The location type determines which buildings are allowed.</p><p>Robotics and nanite factories speed up development. The <a href="/shipyard">Shipyard</a> produces ships, while <a href="/defense">Defense</a> lets you order defensive units and missiles. Ships and defenses share the shipyard queue. The building queue size depends on universe settings and the Architect bonus.</p><p><a href="/research">Research</a> applies to the whole account. Only one research project can run across the account at a time. Starting a project requires a suitable laboratory and resources on the selected planet. Computer technology increases simultaneous fleet slots, engines affect ship speed, and combat technologies improve weapons, shields and armor. The intergalactic research network allows several laboratories to contribute to research speed.</p><p>If an object is unavailable, open its details or the <a href="/tech">technology tree</a> to check required levels, faction and location type. The next level cost and completion time are shown before you start.</p></div></section><section class="content-article-section" id="help-planets"><h2>6. Colonization and military bases</h2><div class="content-article-section-body"><p>In <a href="/galaxy">Galaxy</a>, an address is written as [galaxy:system:position]. A planet, its moon and its debris field may share coordinates but are different targets: always check the selected target type.</p><h3 id="help-colonization">Colonization: founding a new planet</h3><p>A colony is another planet belonging to your account, with its own resources, buildings and production queues. It benefits from technologies you have already researched. Colonization settles an empty position; this mission cannot capture another player''s planet.</p><h3>Requirements for your first colony ship</h3><ul><li><a href="/tech/150">Colonization technology</a> at level 1 or higher. Researching it requires a level 3 laboratory, level 2 armour technology and level 5 energy technology.</li><li>A <a href="/tech/208">Colony Ship</a> requires a level 4 shipyard, level 3 impulse drive and level 1 colonization technology.</li><li>Resources to build the ship, deuterium for the flight and a free fleet slot. The base ship cost is 10,000 metal, 20,000 crystal and 10,000 deuterium; the shipyard shows the final cost after bonuses.</li><li>Room under your ordinary planet limit. Owning a colony ship does not allow you to exceed this limit.</li></ul><h3>How many planets can you own?</h3><p>Your total number of ordinary planets, including your homeworld, cannot exceed <strong>colonization technology level + 1</strong> or the universe cap. For example, level 1 allows a homeworld and one colony; level 2 allows a homeworld and two colonies. The default universe cap is 9 planets. Moons and military bases are counted separately.</p><p>The limit and position availability are checked on arrival. If you send colonizing fleets to several positions with only one planet slot remaining, the first successful colony fills that slot and prevents the others from founding additional planets.</p><h3>Choosing a location</h3><p>Find an empty ordinary position in <a href="/galaxy">Galaxy</a>. With standard settings, positions 1–15 are for planets and position 16 is for expeditions. An empty debris field or a missing moon at an occupied planet does not make that position available for colonization.</p><p>A nearby colony is easier to supply: shorter flights let you move resources and ships sooner. Consider neighbors, temperature and the planned purpose of the colony. Central positions generally offer more building fields, colder outer planets favor deuterium production, and warmer planets improve solar satellite output.</p><p>Field count and temperature are rolled within the ranges for the selected position. The exact size becomes known after settlement; the same position does not guarantee identical planets. Fields limit building development, so assess the available space before investing heavily.</p><h3 id="help-planet-properties">Position, size, temperature and production</h3><p><strong>System position sets the ranges for size and temperature.</strong> When a colony is founded, its field count and maximum temperature are rolled within the ranges for that position. Galaxy and system numbers do not themselves grant production or energy bonuses.</p><p>Overview shows the planet''s <strong>diameter</strong>; its radius is half its diameter. At creation, the relationship to initial field count F is <strong>D = floor(1,000 × √F) km; R = D / 2</strong>. For example, 225 fields give a diameter of 15,000 km and a radius of 7,500 km. Size does not directly increase mining or energy: it provides room for buildings. Terraformers add fields, so diameter alone no longer describes the available space after expansion.</p><p>The table covers new ordinary colonies with the standard size multiplier of ×1; homeworlds and military bases use separate field settings. The universe size multiplier changes initial fields and the corresponding diameter. <strong>T is maximum temperature</strong>, not the average: Overview displays an interval from T − 40 to T. The table lists the possible values of T itself.</p><div class="game-table-wrap content-table-wrap" role="region" aria-labelledby="colony-table-caption" tabindex="0"><table class="game-table content-table"><caption id="colony-table-caption">Colony properties by system position</caption><thead><tr><th scope="col">Position</th><th scope="col">Initial fields</th><th scope="col">T, °C</th><th scope="col">Deuterium multiplier</th><th scope="col">Energy per satellite</th></tr></thead><tbody><tr><th scope="row">1</th><td>95–128</td><td>220…260</td><td>0.40–0.56</td><td>60–66</td></tr><tr><th scope="row">2</th><td>97–130</td><td>170…210</td><td>0.60–0.76</td><td>51–58</td></tr><tr><th scope="row">3</th><td>98–147</td><td>120…160</td><td>0.80–0.96</td><td>43–50</td></tr><tr><th scope="row">4</th><td>123–223</td><td>70…110</td><td>1.00–1.16</td><td>35–41</td></tr><tr><th scope="row">5</th><td>148–230</td><td>60…100</td><td>1.04–1.20</td><td>33–40</td></tr><tr><th scope="row">6</th><td>148–246</td><td>50…90</td><td>1.08–1.24</td><td>31–38</td></tr><tr><th scope="row">7</th><td>141–293</td><td>40…80</td><td>1.12–1.28</td><td>30–36</td></tr><tr><th scope="row">8</th><td>169–266</td><td>30…70</td><td>1.16–1.32</td><td>28–35</td></tr><tr><th scope="row">9</th><td>161–258</td><td>20…60</td><td>1.20–1.36</td><td>26–33</td></tr><tr><th scope="row">10</th><td>154–244</td><td>10…50</td><td>1.24–1.40</td><td>25–31</td></tr><tr><th scope="row">11</th><td>148–224</td><td>0…40</td><td>1.28–1.44</td><td>23–30</td></tr><tr><th scope="row">12</th><td>136–191</td><td>-10…30</td><td>1.32–1.48</td><td>21–28</td></tr><tr><th scope="row">13</th><td>109–141</td><td>-50…-10</td><td>1.48–1.64</td><td>15–21</td></tr><tr><th scope="row">14</th><td>81–113</td><td>-90…-50</td><td>1.64–1.80</td><td>8–15</td></tr><tr><th scope="row">15</th><td>65–94</td><td>-130…-90</td><td>1.80–1.96</td><td>1–8</td></tr></tbody></table></div><p>The deuterium multiplier is the temperature component of the production formula. Satellite energy assumes 100% operation without faction or officer bonuses. Values within each range do not have to occur together: size and temperature are rolled separately.</p><h3>How temperature affects deuterium</h3><p>For a synthesizer of level L at 100% operation with sufficient energy, base hourly production is <strong>10 × L × 1.1<sup>L</sup> × (1.44 − 0.004 × T)</strong>. Universe mining speed, faction and Geologist bonuses, operating level and energy availability also apply, with rounding down during calculation. Fusion reactor consumption reduces net deuterium income.</p><p>Lower T gives more deuterium at the same synthesizer level. At T = +100 °C the temperature multiplier is 1.04; at T = −100 °C it is 1.84. With other conditions equal, the colder planet produces about 77% more deuterium before rounding. The synthesizer''s energy consumption is independent of temperature: at 100% operation it equals floor(20 × L × 1.1<sup>L</sup>).</p><h3>How temperature affects energy</h3><p>Base output from <strong>one solar satellite = floor((T + 140) / 6)</strong>. At T = +100 °C this is 40 energy, but at T = −100 °C it is only 6. Group output depends on satellite count, operating level and faction and Engineer bonuses. Satellites can be destroyed in combat, so account for the potential loss of this energy source.</p><p><strong>Solar plants and fusion reactors are independent of temperature.</strong> At 100% operation, a level L solar plant has a base output of 20 × L × 1.1<sup>L</sup>; a fusion reactor produces 30 × L × (1.05 + 0.01 × E)<sup>L</sup>, where E is energy technology level. Final output accounts for rounding, operating level and energy bonuses. Fusion reactors consume deuterium; energy technology specifically improves their base output.</p><p>Metal and crystal production do not directly depend on temperature or diameter. Central positions generally suit large industrial colonies. Cold outer positions favor deuterium but need stronger energy infrastructure. Warm inner positions give effective satellites but less deuterium. A large planet is not necessarily cold or more productive: assess fields and temperature separately.</p><h3>Sending the mission step by step</h3><ol><li>Build a colony ship in the <a href="/shipyard">Shipyard</a> and select the location where it is stationed.</li><li>Open <a href="/fleet">Fleet</a> and select one colony ship. Add cargo ships with resources for early construction if needed.</li><li>Enter the empty position coordinates and select <strong>Planet</strong> as the target type.</li><li>Choose <strong>Colonise</strong>, set speed and cargo, and check arrival time, fuel consumption and capacity.</li><li>Send the fleet and wait for the result message. Dispatch does not reserve the position: another player may arrive first.</li></ol><h3>What happens on arrival?</h3><p>Success <strong>consumes one colony ship</strong>. All other ships, including extra colony ships, and delivered resources stay on the new planet. There is no automatic return flight. Sending several colony ships in one fleet does not create multiple colonies in one mission.</p><p>If the position has been occupied or your planet limit has been reached, colonization fails and the fleet returns. Read <a href="/messages">Messages</a> for the reason. Research the next technology level or choose another empty position as appropriate.</p><h3>Getting the colony started</h3><p>Select the new planet from your locations and open <a href="/overview">Overview</a> to check fields, temperature and supplies and choose a name. Start with energy and mining, then develop the robotics factory, storage and other infrastructure you need. Buildings from your homeworld are not copied to the colony.</p><p>Use Transport for further supplies: ships unload resources and return. Use Stay to relocate ships to the colony: they remain at the destination. Compare all your planets in <a href="/empire">Empire</a>.</p><h3>Military bases</h3><p>A Create a base mission requires a Mobile Base and an empty position. The maximum number of military bases equals your Military Base research level. Establishing a base consumes one Mobile Base ship; escorts and cargo stay at the new location.</p><p>A military base is an outpost with a limited building selection, including jump gates and missile silos. It does not replace a mining colony: supplies must be delivered. Use <a href="/empire">Empire</a> for a consolidated view of your locations.</p></div></section><section class="content-article-section" id="help-fleet"><h2>7. Ships and fleet dispatch</h2><div class="content-article-section-body"><ul><li><strong>Small and Large Cargo ships</strong> transport resources and carry loot. Remember their weak armament when attacking.</li><li><strong>Light and Heavy Fighters, Cruisers, Battleships and Battlecruisers</strong> form combat groups. Their usefulness depends on the enemy, technologies and rapid fire.</li><li><strong>Bombers and Destroyers</strong> help against fortified targets; still check the opposing force in the simulator.</li><li><strong>The Death Star</strong> is a heavy, slow ship required for attempts to destroy a moon.</li><li><strong>Recyclers, Espionage Probes, Colony Ships and Mobile Bases</strong> enable their specialist missions. Faction ships complement your combat fleet.</li><li><strong>Solar Satellites</strong> generate energy in orbit and cannot take part in ordinary flights.</li></ul><p>In <a href="/fleet">Fleet</a>, choose ships, coordinates, target type, speed, mission and cargo. Before sending, check arrival and return times, deuterium consumption and free cargo space. The slowest ship limits group speed, and fuel occupies part of the hold.</p><p>The basic fleet limit is one plus your computer technology level. An active Admiral adds two slots. Different missions share this limit; expeditions also have a separate cap. Use <a href="/fleet/shortcut">coordinate shortcuts</a> for frequent destinations.</p></div></section><section class="content-article-section" id="help-missions"><h2>8. Fleet missions</h2><div class="content-article-section-body"><ul><li><strong>Attack.</strong> Fight at another player’s location and potentially capture some resources. Surviving ships return with loot up to their cargo capacity.</li><li><strong>United Attack.</strong> Join a coordinated attack. Manage the group and invitations through the attacking fleet controls.</li><li><strong>Transport.</strong> Deliver resources, then return the ships. Also used to supply your own locations.</li><li><strong>Stay.</strong> Move ships and cargo to your own location. Successful arrival has no automatic return flight.</li><li><strong>Hold.</strong> Temporarily station a fleet at another player’s location to help defend it. Holding requires additional deuterium; the fleet returns afterwards.</li><li><strong>Spy.</strong> Use probes to gather information about another location. Probes may be destroyed.</li><li><strong>Colonise.</strong> Establish an ordinary colony using a colony ship.</li><li><strong>Harvest.</strong> Collect metal and crystal from a debris field with recyclers. Select the debris field rather than the planet.</li><li><strong>Destroy.</strong> Attempt to destroy an enemy moon with Death Stars after winning the battle. The attempt can fail, and the dispatched fleet may be lost.</li><li><strong>Create a base.</strong> Establish a military base using a Mobile Base ship.</li><li><strong>Expedition.</strong> Explore the distant position of a system for a random outcome.</li></ul><p><strong>Interplanetary attacks</strong> are launched separately with missiles through Galaxy: they strike defenses rather than moving ships. Available fleet missions depend on ships, target type, research and dispatch restrictions.</p><p>Resource transfers to the same other player are limited to one dispatch in the past 24 hours and three in the past 7 days. Transport to a player absent for more than 7 days is unavailable. Transfers between your own locations are exempt from these limits. Also follow the <a href="/content/rules">rules on trading and assistance</a>.</p></div></section><section class="content-article-section" id="help-expeditions"><h2>9. Expeditions</h2><div class="content-article-section-body"><p>Research expedition technology and select the position immediately after the last ordinary planet slot: in a system with 15 planet slots, this is position 16. The fleet cannot consist solely of espionage probes.</p><p>Choose an available exploration duration. Technology increases the maximum duration and number of expedition groups. You also need a free slot under the overall fleet limit.</p><p>An expedition may find resources, credits or ships, find nothing, be delayed, enter combat or disappear entirely. Leave room for discoveries and send only forces you can afford to lose. Results arrive in Messages; the return may be later than originally calculated.</p></div></section><section class="content-article-section" id="help-combat"><h2>10. Espionage, combat and defense</h2><div class="content-article-section-body"><p>The detail in an espionage report depends on probe count and the difference in espionage levels, including bonuses. A missing report section does not mean there is no fleet or defense. Reports describe the moment of the scan; conditions may change before your attack arrives.</p><p>Combat accounts for the forces on each side, weapons, shields, armor and rapid fire: additional shots against particular target types. No composition is invincible. Compare losses, loot and debris in the <a href="/sim">simulator</a>; its calculation does not guarantee the same result in a real battle.</p><p>Rocket launchers and lasers provide numerous defensive units, complemented by Gauss cannons, ion and plasma weapons and shield domes. Some defenses may be restored after an ordinary battle. Repair and debris rates depend on settings and bonuses.</p><p>Interplanetary missiles strike defenses within range in the same galaxy. Launching requires a missile silo of at least level 4 and an impulse engine; the engine also increases range. Anti-ballistic missiles automatically counter missile strikes. Silo capacity limits your missile stock.</p><p>After combat, read the report in <a href="/messages">Messages</a> and send recyclers if you want the debris. Victory does not reserve the field for you: other players can collect it.</p></div></section><section class="content-article-section" id="help-safety"><h2>11. New player protection and fleet safety</h2><div class="content-article-section-body"><p>When new player protection is enabled, hostile fleet dispatch to an active target below the points threshold is blocked. The game also checks whether the sender exceeds the target’s points by more than the permitted factor. Defaults are 5,000 points and a factor of 5; universe settings can change them.</p><p>These checks cover attacks, joint attacks, espionage, moon destruction and holding, with an exception for holding at your own alliance. They are disabled for a target absent for more than 7 days or blocked. Missile strikes have separate conditions, so new player protection does not mean complete immunity.</p><p>Avoid leaving large stockpiles and valuable fleets unattended. To protect ships while away, choose a suitable flight with cargo and time its arrival for when you can play. Consider phalanx visibility, recall options and the destination: once the fleet arrives, it may be targeted again. An expedition with a risk of total loss is unsuitable for safe storage.</p></div></section><section class="content-article-section" id="help-moons"><h2>12. Moons, phalanxes and jump gates</h2><div class="content-article-section-body"><p>A moon may form after a battle at an ordinary planet that does not already have one. The chance is calculated from that battle’s debris and capped by universe settings; an active Admiral on the defending account raises the cap. Even the maximum chance does not guarantee success. Moon formation does not collect the debris field for you.</p><p>Moons have no mining, so deliver supplies by transport. A lunar base increases building fields. A moon can be attacked and destroyed; owning one does not make your fleet invulnerable.</p><h3>Sensor phalanx</h3><p>A phalanx operates from the selected moon and scans planets in the same galaxy. Its range in either direction is the square of its level minus one: level 1 covers its own system, level 2 reaches 3 systems away, and level 3 reaches 8. Each scan consumes 5,000 deuterium on the moon.</p><p>The phalanx shows movements and arrival times visible to it that involve the scanned planet. It does not reveal every flight: for example, flights between moons and flights from a moon to debris are not visible.</p><h3>Jump gates</h3><p>Gates instantly move ships between your own moons and military bases with operational, ready gates. Select the destination during fleet dispatch. Resources cannot pass through gates. Both gates recharge after a jump; higher levels shorten the wait.</p></div></section><section class="content-article-section" id="help-alliance"><h2>13. Alliances and joint operations</h2><div class="content-article-section-body"><p>In <a href="/alliance">Alliance</a>, create an alliance or apply to an existing one. Alliances provide member lists, private chat, ranks with permissions, application management and diplomacy. Your rank determines access to management tools.</p><p>For a joint attack, create a group from a dispatched attacking fleet, invite participants and add forces using the joint attack mission. Check group availability and the final arrival time: joining is subject to flight conditions.</p><p>Use Hold for joint defense. The alliance depot can supply holding fleets with deuterium. Diplomatic agreements may prevent attacks. Alliance membership does not waive the resource transfer rules.</p></div></section><section class="content-article-section" id="help-rewards"><h2>14. Quests, experience and daily bonuses</h2><div class="content-article-section-body"><p><a href="/quests">Quests</a> introduce game mechanics and reward resources, credits, object levels, ships, defenses or officer time. Some unlock after earlier quests or particular development levels.</p><p>Open a quest before working on it, read its conditions and claim the reward when finished. Conditions involving buildings and ships may be checked at the selected location; resources and local rewards are delivered there as well. If completion is unavailable, check the selected planet and all prerequisites.</p><p>Industrial experience comes from developing eligible buildings, while military experience comes from battle results. These are separate from ranking points. Leveling up awards credits and may unlock quests; Overview shows your progress.</p><p>Claim the daily bonus manually. The next claim becomes available after 24 hours, and resources go to the selected location. Consecutive claims increase the reward and add an extra credit from the second claim in a streak. A long gap resets the streak; follow the bonus timer.</p></div></section><section class="content-article-section" id="help-credits"><h2>15. Credits, trading and officers</h2><div class="content-article-section-body"><p>Credits are an account-wide currency. Sources include levels, some quests, expedition finds, continued daily bonus streaks and referrals. <a href="/credits">Credits</a> lists available top-up methods.</p><p>The <a href="/merchant">Merchant</a> exchanges resources at the selected location at the displayed rate. Each exchange costs 1 credit. On ordinary planets, Resources also offers the displayed resource package for 10 credits, with a 48-hour wait before the next purchase on that planet.</p><p><a href="/officiers">Officers</a> are hired for a limited period. Hiring an active officer again extends the duration rather than doubling the effect.</p><ul><li><strong>Geologist</strong> improves production and storage capacity.</li><li><strong>Admiral</strong> adds fleet slots, speeds up ships, reduces their cost and affects moon operations.</li><li><strong>Engineer</strong> improves energy production, reduces defense costs and helps reduce losses.</li><li><strong>Technocrat</strong> speeds up research and improves espionage.</li><li><strong>Architect</strong> expands the building queue and speeds up construction of buildings, ships and defenses.</li><li><strong>Metaphysicist</strong> reduces flight fuel consumption.</li><li><strong>Mercenary</strong> improves weapons, shields and armor.</li></ul><p>Check each officer card for exact effects, prices and durations. <a href="/referrals">Referrals</a> provides your invitation link and information about invited friends; their level gains reward the inviting player.</p></div></section><section class="content-article-section" id="help-statistics"><h2>16. Rankings and records</h2><div class="content-article-section-body"><p><a href="/stats">Statistics</a> compares players, alliances and factions by total, building, research, fleet and defense points. Points reflect the base resource cost of existing objects and levels: 1,000 resources equal one point. Stored resources do not award points by themselves.</p><p>Fleets in flight count. Ship losses, demolished buildings and lost locations may reduce points. Fleet and research rankings account for cost, not just ship or level counts. Statistics update periodically, so rank changes may not appear immediately.</p><p><a href="/records">Records</a> lists achievements for individual objects, and the <a href="/hall">Hall of Fame</a> features major battles. Settings let you control participation in records.</p></div></section><section class="content-article-section" id="help-tools"><h2>17. Communication and useful tools</h2><div class="content-article-section-body"><ul><li><a href="/messages">Messages</a> contains personal correspondence and espionage, battle and mission results. You can also report a message here.</li><li><a href="/chat">Chat</a> is for talking to other players; alliance chat is available separately.</li><li><a href="/friends">Friends</a> and <a href="/search">Search</a> help you find players and keep in touch.</li><li><a href="/notes">Notes</a> stores your personal reminders.</li><li><a href="/logs">Battle logs</a> lets you save reports for viewing and discussion.</li><li><a href="/support">Support</a> handles bugs and game questions. Include coordinates, the event time and a report if available.</li></ul><p>Read the <a href="/content/rules">XNova rules</a> before trading, arranging battles or conducting joint operations. If you cannot log in, use <a href="/contacts">Contacts</a>.</p></div></section><section class="content-article-section" id="help-vacation"><h2>18. Settings and vacation mode</h2><div class="content-article-section-body"><p><a href="/options">Settings</a> lets you change language, interface preferences, email and password. Keep access to your linked email for account recovery.</p><p>Enable vacation mode for a long absence. All account queues must finish and your own fleets must return first. Vacation stops mining and restricts game actions; new fleet dispatches to your locations are blocked except debris recycling.</p><p><strong>Fleets already on their way to you are not canceled.</strong> Vacation mode does not stop an attack already launched. The minimum duration is set by the universe and defaults to 2 days. Once that time has passed, leave vacation mode manually. Then check production levels in Resources: entering vacation sets them to zero.</p></div></section><section class="content-article-section" id="help-faq"><h2>19. Common questions</h2><div class="content-article-section-body"><h3>Why is production low or stopped?</h3><p>Check energy, full storage, operating percentages and vacation mode. Moons and military bases have no production, and fusion reactors need deuterium.</p><h3>Why can I not send a fleet?</h3><p>Check free slots, ships and fuel, cargo capacity, coordinates and target type. Some missions require special ships, technologies or a group invitation. Consider vacation mode, new player protection, diplomacy and resource transfer limits.</p><h3>Why was no colony or base created?</h3><p>Read the mission message: another fleet may have claimed the position before arrival, or you may have reached your limit. Research the appropriate technology and check your empire capacity before sending again.</p><h3>Why can I not change faction or enter vacation mode?</h3><p>Check queues at every location and your fleets in flight. Changing faction also requires a free change or enough credits.</p><p><a href="#help-contents">Back to contents</a></p></div></section></div>');
INSERT INTO `contents` (`title_ru`, `alias`, `html_ru`, `title_en`, `html_en`) VALUES ('Пользовательское соглашение', 'agreement', '<div class="content-article"><section class="content-article-section"><h2>1. О проекте и соглашении</h2><div class="content-article-section-body"><p>XNova — бесплатная браузерная стратегическая игра с открытым исходным кодом. Проект развивается при поддержке сообщества, а все денежные пожертвования направляются на его развитие и поддержку работы игры. Это соглашение определяет условия использования игры и связанных с ней страниц сайта. Под администрацией понимается команда, которая поддерживает проект.</p><p>При регистрации вы принимаете это соглашение и <a href="/content/rules">правила игры</a>. Если условия вам не подходят, не создавайте аккаунт и не пользуйтесь игрой. Несовершеннолетние могут участвовать только с согласия законного представителя и с учётом возрастных ограничений, установленных применимым законодательством.</p></div></section><section class="content-article-section"><h2>2. Аккаунт и участие в игре</h2><div class="content-article-section-body"><p>Участие в игре на этом сервере предназначено для личного некоммерческого использования. Это условие не ограничивает права на исходный код, предоставленные его лицензиями. Количество аккаунтов, временный уход за чужим аккаунтом, обмен аккаунтами и другие игровые ограничения регулируются правилами игры.</p><p>Защищайте пароль и доступ к привязанной электронной почте. Не передавайте данные для входа за пределами случаев, разрешённых правилами. Для восстановления доступа администрация может запросить подтверждение владения аккаунтом; само обращение не гарантирует восстановления.</p><p>Вы самостоятельно обеспечиваете доступ в интернет, выбираете устройство и время, которое проводите в игре.</p></div></section><section class="content-article-section"><h2>3. Честная игра и общение</h2><div class="content-article-section-body"><p>Соблюдайте правила игры и уважайте других участников. Запрещены использование ошибок ради преимущества, неразрешённая автоматизация, обход ограничений, вмешательство в работу сервера и попытки получить доступ к чужим аккаунтам или закрытым данным.</p><p>Не размещайте угрозы, травлю, спам, вредоносные материалы, чужие персональные данные без законного основания и материалы, нарушающие права других лиц. Не выдавайте себя за администрацию. Об ошибках и нарушениях сообщайте через <a href="/support">поддержку</a>.</p><p>Администрация может проверять нарушения по игровым журналам и обращениям, удалять нарушающие правила материалы, отменять результаты запрещённых действий и ограничивать доступ к аккаунтам в соответствии с правилами игры.</p></div></section><section class="content-article-section"><h2>4. Работа проекта и изменения</h2><div class="content-article-section-body"><p>Игра предоставляется «как есть» и в том виде, в котором доступна в момент использования. Администрация не предоставляет дополнительных гарантий бесперебойной работы, отсутствия ошибок, совместимости с любым устройством или соответствия игры ожиданиям пользователя.</p><p>Возможны технические перерывы, сбои, откаты, потеря игровых данных и изменение результатов игровых действий. Администрация не гарантирует сохранность аккаунта, флотов, ресурсов, рейтинга и другого прогресса, восстановление потерь или исправление ошибок в определённый срок.</p><p>Администрация может менять баланс, механики, интерфейс и состав доступных функций, проводить технические работы, приостанавливать или прекращать работу проекта. Соглашение не устанавливает гарантированный срок работы проекта или обязательный срок предварительного уведомления, кроме случаев, когда это требуется законом.</p></div></section><section class="content-article-section"><h2>5. Добровольные донаты и игровые ценности</h2><div class="content-article-section-body"><p>Ресурсы, флоты, планеты, кредиты и другие игровые показатели используются внутри XNova. Они не являются денежным вкладом, средством платежа вне игры или обещанием заработка. Игра не предусматривает их обмен на реальные деньги или выкуп администрацией.</p><p>Вы можете добровольно поддержать развитие игры денежным пожертвованием — донатом. Донат не является обязательным условием участия, инвестицией, заказом разработки конкретной функции или обещанием завершить её к определённому сроку. Поддержка проекта не даёт права управлять им, не освобождает от правил и не гарантирует сохранность прогресса, победу или бессрочную работу сервера.</p><p>Если при переводе указаны условия начисления кредитов или предоставления игровых бонусов, учитываются эти условия и требования закона. Название перевода «донат» само по себе не отменяет связанных с ним обязательств. Вопросы ошибочных переводов и возвратов можно направить в поддержку; они разрешаются с учётом применимого законодательства. Соглашение не устанавливает безусловный запрет на возврат средств.</p></div></section><section class="content-article-section"><h2>6. Пределы ответственности</h2><div class="content-article-section-body"><p>В пределах, допускаемых применимым законодательством, администрация не отвечает за убытки, упущенную выгоду и иные потери, связанные с использованием игры или невозможностью получить к ней доступ, включая последствия сбоев, утраты прогресса, действий других игроков, неполадок устройств, интернет-соединения и сторонних сервисов.</p><p>Потраченное на игру время, изменение рейтинга и утрата игровых ценностей сами по себе не создают обещания денежной компенсации. Возможное восстановление прогресса или предоставление игровых бонусов по решению администрации не означает гарантии таких мер в других случаях.</p><p>Ограничения этого раздела действуют только там, где они разрешены законом. Соглашение не исключает ответственность, которую нельзя исключить или ограничить, в том числе за умышленное нарушение обязательств, и не лишает пользователя обязательных законных прав.</p></div></section><section class="content-article-section"><h2>7. Данные и материалы</h2><div class="content-article-section-body"><p>Для работы аккаунтов, авторизации и защиты игры используются регистрационные данные, технические cookies, IP-адреса и журналы игровых действий. Не размещайте в общедоступных разделах сведения, которые не хотите раскрывать другим участникам.</p><p>Это соглашение не является согласием на произвольный сбор, распространение или использование персональных данных. Обработка данных требует предусмотренного законом основания, а когда необходимо отдельное согласие, принятие соглашения его не заменяет.</p><p>Исходный код XNova распространяется по лицензии MIT. Полный текст лицензии находится в файле LICENSE в корне репозитория проекта. Использование, изучение, копирование, изменение и распространение кода допускаются на условиях MIT с сохранением уведомления об авторских правах и текста лицензии. Сторонние компоненты сохраняют собственные лицензии. Это соглашение не ограничивает права, предоставленные такими лицензиями. Открытость кода не разрешает вмешиваться в работу чужого сервера или получать доступ к закрытым данным.</p><p>Права на оформление, изображения, тексты и другие материалы сохраняются за соответствующими правообладателями. Лицензия исходного кода не распространяется автоматически на все материалы игры: для них учитываются собственные лицензии и разрешения правообладателей.</p></div></section><section class="content-article-section"><h2>8. Прекращение участия</h2><div class="content-article-section-body"><p>Вы можете в любое время прекратить пользоваться игрой. Ограничение доступа за нарушение правил и прекращение работы проекта означают, что дальнейшее использование соответствующих игровых возможностей может стать недоступным.</p><p>Прекращение участия или блокировка аккаунта не отменяют прав и обязательств, которые сохраняются по закону, включая вопросы ранее совершённых денежных переводов.</p></div></section><section class="content-article-section"><h2>9. Актуальная редакция и обращения</h2><div class="content-article-section-body"><p>Действующая редакция размещается на <a href="/content/agreement">этой странице</a>. Администрация может обновлять соглашение. Новая редакция применяется к дальнейшему использованию игры в пределах, допускаемых законом; публикация изменений сама по себе не отменяет ранее возникших обязательств. Если закон требует уведомления или отдельного согласия, одного размещения текста недостаточно.</p><p>По вопросам игры и соглашения обращайтесь в <a href="/support">поддержку</a>. Если вход в аккаунт недоступен, используйте страницу <a href="/contacts">«Контакты»</a>. Обращение в поддержку не ограничивает предусмотренные законом способы защиты ваших прав.</p></div></section></div>', 'User Agreement', '<div class="content-article"><section class="content-article-section"><h2>1. About the project and this agreement</h2><div class="content-article-section-body"><p>XNova is a free, open-source browser strategy game. The project is developed with community support, and all monetary donations go towards its development and keeping the game running. This agreement sets out the terms for using the game and its associated website pages. The administration means the team that maintains the project.</p><p>By registering, you accept this agreement and the <a href="/content/rules">game rules</a>. If you do not agree to these terms, do not create an account or use the game. Minors may participate only with the consent of a legal representative and subject to any age restrictions under applicable law.</p></div></section><section class="content-article-section"><h2>2. Your account and participation</h2><div class="content-article-section-body"><p>Playing on this server is intended for personal, non-commercial use. This condition does not restrict any rights to the source code granted by its licenses. The number of accounts, temporary account sitting, account exchanges and other gameplay restrictions are governed by the game rules.</p><p>Keep your password and access to your linked email account secure. Do not share login details except where permitted by the rules. The administration may request proof of account ownership when you seek to restore access; submitting a request does not guarantee recovery.</p><p>You are responsible for arranging your internet access, choosing your device and deciding how much time you spend playing.</p></div></section><section class="content-article-section"><h2>3. Fair play and communication</h2><div class="content-article-section-body"><p>Follow the game rules and respect other participants. Exploiting bugs for an advantage, unauthorized automation, bypassing restrictions, interfering with server operations and attempting to access accounts belonging to others or restricted data are prohibited.</p><p>Do not post threats, harassment, spam, malicious content, personal data belonging to others without a lawful basis, or material that infringes the rights of others. Do not impersonate the administration. Report bugs and violations through <a href="/support">support</a>.</p><p>The administration may investigate violations using game logs and reports, remove content that violates the rules, reverse the results of prohibited actions and restrict account access in accordance with the game rules.</p></div></section><section class="content-article-section"><h2>4. Project availability and changes</h2><div class="content-article-section-body"><p>The game is provided &ldquo;as is&rdquo; and as available at the time of use. The administration provides no additional guarantees of uninterrupted operation, freedom from errors, compatibility with every device or suitability for your expectations.</p><p>Maintenance downtime, failures, rollbacks, loss of game data and changes to the results of game actions may occur. The administration does not guarantee the preservation of accounts, fleets, resources, rankings or other progress, the restoration of losses, or bug fixes within a specific period.</p><p>The administration may change the balance, mechanics, interface and available features, carry out maintenance, suspend the project or shut it down. This agreement does not establish a guaranteed period of operation or a mandatory advance notice period, except where required by law.</p></div></section><section class="content-article-section"><h2>5. Voluntary donations and in-game assets</h2><div class="content-article-section-body"><p>Resources, fleets, planets, credits and other game values are used within XNova. They are not a monetary deposit, a means of payment outside the game or a promise of earnings. The game does not provide for their exchange for real money or their repurchase by the administration.</p><p>You may voluntarily support game development with a monetary donation. A donation is not a requirement for participation, an investment, a commission to develop a particular feature or a promise to complete it by a particular deadline. Supporting the project does not give you the right to control it, exempt you from the rules or guarantee the preservation of progress, victory or indefinite server operation.</p><p>If a transfer specifies terms for awarding credits or in-game bonuses, those terms and legal requirements apply. Calling a transfer a &ldquo;donation&rdquo; does not by itself remove the obligations associated with it. Questions about mistaken transfers and refunds may be submitted to support and are handled in accordance with applicable law. This agreement does not impose an unconditional ban on refunds.</p></div></section><section class="content-article-section"><h2>6. Limitations of liability</h2><div class="content-article-section-body"><p>To the extent permitted by applicable law, the administration is not liable for damages, lost profits or other losses related to using the game or being unable to access it, including the consequences of failures, lost progress, actions of other players, device problems, internet connection issues and third-party services.</p><p>Time spent playing, changes in ranking and loss of in-game assets do not by themselves constitute a promise of monetary compensation. Any restoration of progress or award of in-game bonuses at the discretion of the administration does not guarantee such measures in other cases.</p><p>The limitations in this section apply only where permitted by law. This agreement does not exclude liability that cannot legally be excluded or limited, including liability for intentional breaches of obligations, and does not deprive you of mandatory statutory rights.</p></div></section><section class="content-article-section"><h2>7. Data and materials</h2><div class="content-article-section-body"><p>Registration data, technical cookies, IP addresses and game activity logs are used to operate accounts, authenticate users and protect the game. Do not post information in public areas that you do not wish to disclose to other participants.</p><p>This agreement does not constitute consent to arbitrary collection, disclosure or use of personal data. Data processing requires a lawful basis, and where separate consent is required, accepting this agreement does not replace it.</p><p>The XNova source code is distributed under the MIT License. The full license text is in the LICENSE file at the root of the project repository. Use, study, copying, modification and distribution of the code are permitted under the MIT terms, with the copyright notice and license text retained. Third-party components retain their own licenses. This agreement does not restrict the rights granted by those licenses. Open access to the code does not authorize interference with a server belonging to someone else or access to restricted data.</p><p>Rights to the design, images, text and other materials remain with their respective rights holders. The source code license does not automatically apply to all game materials: their own licenses and permissions from rights holders must be taken into account.</p></div></section><section class="content-article-section"><h2>8. Ending your participation</h2><div class="content-article-section-body"><p>You may stop using the game at any time. Restrictions imposed for rule violations and the closure of the project may make the relevant game features unavailable for further use.</p><p>Ending your participation or having your account blocked does not remove rights and obligations that survive under law, including matters relating to previous monetary transfers.</p></div></section><section class="content-article-section"><h2>9. Current version and contact</h2><div class="content-article-section-body"><p>The current version is published on <a href="/content/agreement">this page</a>. The administration may update this agreement. An updated version applies to subsequent use of the game to the extent permitted by law; publishing changes does not by itself cancel obligations that have already arisen. Where the law requires notice or separate consent, merely publishing the text is not sufficient.</p><p>For questions about the game or this agreement, contact <a href="/support">support</a>. If you cannot sign in to your account, use the <a href="/contacts">Contacts</a> page. Contacting support does not limit the legal remedies available to protect your rights.</p></div></section></div>');
INSERT INTO `contents` (`title_ru`, `alias`, `html_ru`, `title_en`, `html_en`) VALUES ('Добро пожаловать в XNova', 'welcome', '<p>Добро пожаловать в XNova — вселенную, где история великих империй начинается с одной планеты.</p><p>Превратите скромную колонию в могущественную державу. Возводите неприступную оборону, развивайте промышленность и открывайте технологии, способные изменить ход войны.</p><p>Отправляйте флот к далёким мирам, сражайтесь за богатства галактики и расширяйте границы своей империи. Заключайте союзы с другими правителями, торгуйте ресурсами или бросайте вызов тем, кто встанет на вашем пути.</p><p>Ваш путь к господству начинается с выбора одной из четырёх рас. Каждая обладает своими преимуществами и уникальным кораблём.</p><div style="display:flex;justify-content:center;align-items:center;gap:12px;flex-wrap:wrap;margin-top:12px;"><img src="/assets/images/icons/races/confederation.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Конфедерация"> <img src="/assets/images/icons/races/bionics.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Бионики"> <img src="/assets/images/icons/races/cylons.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Сайлоны"> <img src="/assets/images/icons/races/ancients.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Древние"></div>', 'Welcome to XNova', '<p>Welcome to XNova, a universe where the story of a great empire begins on a single planet.</p><p>Raise a mighty realm from a fledgling colony. Build formidable defenses, develop your industry, and unlock technologies that can turn the tide of war.</p><p>Send your fleet to distant worlds, fight for the riches of the galaxy, and push the borders of your empire ever farther. Forge alliances with other rulers, trade resources, or challenge those who stand in your way.</p><p>Your path to dominion begins with a choice of four races. Each has its own strengths and a unique ship.</p><div style="display:flex;justify-content:center;align-items:center;gap:12px;flex-wrap:wrap;margin-top:12px;"><img src="/assets/images/icons/races/confederation.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Confederation"> <img src="/assets/images/icons/races/bionics.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Bionics"> <img src="/assets/images/icons/races/cylons.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Cylons"> <img src="/assets/images/icons/races/ancients.svg" width="64" height="64" style="width:64px;height:64px;flex:none;" alt="Ancients"></div>');
INSERT INTO `contents` (`title_ru`, `alias`, `html_ru`, `title_en`, `html_en`) VALUES ('Оплата выполнена успешно', 'success', '<div class="separator"></div><table class="table"><tr><th><br>Вы успешно пополнили ваш игровой счет!<br><br></th></tr></table>', NULL, NULL);
INSERT INTO `contents` (`title_ru`, `alias`, `html_ru`, `title_en`, `html_en`) VALUES ('Оплата не произведена', 'fail', '<div class="separator"></div><table class="table"><tr><th><br>Произошла ошибка при попытке пополнения игрового счета!<br><br></th></tr></table>', NULL, NULL);
